import{_ as e,o as c,c as d,a2 as t}from"./chunks/framework.xCjF2uVY.js";const p=JSON.parse('{"title":"验收门读数","description":"一条命令跑的数字门: 当前读数、判据与夹具","frontmatter":{"title":"验收门读数","description":"一条命令跑的数字门: 当前读数、判据与夹具"},"headers":[],"relativePath":"acceptance.md","filePath":"acceptance.md","lastUpdated":null}'),s={name:"acceptance.md"};function r(n,o,a,l,i,g){return c(),d("div",null,[...o[0]||(o[0]=[t('<h1 id="验收门读数" tabindex="-1">验收门读数 <a class="header-anchor" href="#验收门读数" aria-label="Permalink to &quot;验收门读数&quot;">​</a></h1><p>一条命令出全部读数(不重编 / 重编并逐位复现):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 tools/acceptance_gate.py</span></span>\n<span class="line"><span>python3 tools/acceptance_gate.py --rebuild</span></span></code></pre></div><p>实跑统计:<strong>41 项(39 PASS + 2 WARN + 0 FAIL)</strong>,<code>--rebuild</code> <strong>92 项</strong>。</p><p>通则:<strong>空判据一律 FAIL</strong>——解析不到行、字段是哨兵 <code>-1</code>、结论词与数字脱钩、tag 串台,都判失败而不是跳过。每道内嵌判据都配 <code>--selftest</code> 夹具(把某个数改成越界的值必须判 FAIL),门不采信被检工具自己印的结论词。</p><p>本页由 <code>tools/gen_site.py</code> 从 <code>docs/scene-port.md</code> §4 逐行生成,不在站里维护第二份读数。</p><p>每条的<strong>完整判据与反证过程</strong>在 <code>docs/scene-port.md</code> 与 <code>evidence/*/manifest.txt</code>;本页保留原文,只是把三列宽表拆成一节一条,好读。</p><h2 id="s0-资产完好" tabindex="-1">S0 资产完好 <a class="header-anchor" href="#s0-资产完好" aria-label="Permalink to &quot;S0 资产完好&quot;">​</a></h2><blockquote><p>实现:<code>tools/asset_verify.py</code></p></blockquote><p><code>object:378/0 other:539/1 room:388/0 scene:101/0 static:102/0</code>（dmadata 那条是良性例外）。计划风险 7 只要&quot;重生成前留<strong>一份</strong>基线输出&quot;，实际落地更强：这一行在<strong>每次默认档门跑</strong>都重判一遍（<code>--rebuild</code> 亦然），<code>--fast</code> 才是唯一跳过它的档，而那一档明说&quot;少跑 S0 一行 ⇒ 不比对&quot;而不是静默放行</p><h2 id="s1-房间-dl-对账" tabindex="-1">S1 房间 DL 对账 <a class="header-anchor" href="#s1-房间-dl-对账" aria-label="Permalink to &quot;S1 房间 DL 对账&quot;">​</a></h2><blockquote><p>实现:<code>tools/room_reconcile.py</code></p></blockquote><p><strong>32/32</strong>：room_0 694 顶点/408 三角形、room_1 1061/610（opa 608 + xlu 2）、两间 <code>G_MTX==0</code>、Σn==去重顶点（room_1 92 次调用）、母 DL 每条子 DL 的 tri 之和==房间总 tri、room_1 13/13 条 DL 收到 <code>G_ENDDL</code>、零 issue、索引口径 ×2 胜（610 tri/967 引用 vs ×1 的 457/492）、纹理字节守恒与 <code>dxt==CALC_DXT</code> 逐张一致（room_0 7/7、room_1 15/15）、TLUT 命令数==记录数（room_0 5/5 一页、room_1 18/18 两页，各 256 色）、bbox/地面 y/COL/出生点四组互咬</p><h2 id="s2-纹理预算-tlut" tabindex="-1">S2 纹理预算/TLUT <a class="header-anchor" href="#s2-纹理预算-tlut" aria-label="Permalink to &quot;S2 纹理预算/TLUT&quot;">​</a></h2><blockquote><p>实现:<code>tools/room_tex_budget.py</code></p></blockquote><p><strong>13/13</strong>；B5 每房间预算<strong>现读</strong> room_0 <strong>19456 B</strong>（纹 18944 + TLUT 512）、room_1 <strong>49920 B</strong>（纹 48896 + TLUT 1024）、两房间合计 <strong>69376 B</strong> ≤ 262144 B（配方就是 <code>python3 tools/room_tex_budget.py</code> 末尾三行；同一批读数逐行抄在 <code>evidence/room_tex/manifest.txt:29-33</code>，那条&quot;计划风险 1 的答案：不超、不需要分批上传&quot;就落在这个数上）。机内实测另看 <code>VRAMMAP=1</code>：<strong>2026-10-08 重测为两批</strong> —— 房间 22 张 / 66 KB / hi 66 KB / 零重叠，Link 的 17 张 / 22 KB / lo 66 KB / hi 89 KB / bad 0(<code>src_scene/link_rigid.c</code> 的 <code>linkVramMap</code>，同寄存器同公式)，读数来自 GPU 寄存器回读（<code>GFX_TEX_FORMAT</code>）而非编译期常量 ⇒ 与 CPU 侧那 69376 B 是<strong>两个独立量具</strong>（<code>evidence/vrammap/manifest.txt:10,21-26</code>）。⚠ 本行此前抄的是「room_0 13312 B、room_1 32512 B」。<strong>根因不是过期，是口径混用</strong>：那两个数至今仍在被现印——它们是 <code>tools/room_reconcile.py</code> 的 <strong>G10 行</strong>输出，量的是 N64 侧 <code>LOADBLOCK</code> 传输量（<code>(lrs+1)×加载位宽</code>，<code>tools/room_extract.py:475</code>）；而 B5 量的是 NDS 侧 VRAM 占用（<code>w×h×2 B/像素</code>，且一个调色板变体各占一份，<code>tools/room_tex_budget.py:66</code>）。反事实可核：这两台量具与两份房间 JSON 都最后一次落在同一个 <code>499d77c</code>，工作区对这四个路径无改动，所以 B5 从那次落库起就只印 19456/49920——13312 从来不是它的读数。本行的&quot;实现&quot;列点名的是 <code>room_tex_budget.py</code>，抄的却是隔壁工具的合法读数，读者按行索引去复核就会判成&quot;数字对不上&quot;。教训与&quot;手抄数字要有机器出处&quot;同源，但<strong>出处错了比出处缺失更难查</strong>，因为两个数都能现印。另记：本轮第一次更正时我把它判成&quot;旧值过期&quot;，那句本身也是未经上述反事实核实的断言，现已作废。这一格仍<strong>没有机器判</strong>（与「逐位复现 ×29 → 33」同一类缺陷，那一处后来被 <code>--check</code> 的 AST 名单钉住了，这一处仍然靠人）</p><h2 id="s2b-调色板对照功率" tabindex="-1">S2b 调色板对照功率 <a class="header-anchor" href="#s2b-调色板对照功率" aria-label="Permalink to &quot;S2b 调色板对照功率&quot;">​</a></h2><blockquote><p>实现:<code>tools/room_palette_power.py</code></p></blockquote><p>全部 CI 纹理可判比例 ≥50% ⇒ 后面 room_tex_probe 的&quot;正确调色板 vs 错位调色板&quot;不是空判据</p><h2 id="s4-剔除不变量" tabindex="-1">S4 剔除不变量 <a class="header-anchor" href="#s4-剔除不变量" aria-label="Permalink to &quot;S4 剔除不变量&quot;">​</a></h2><blockquote><p>实现:<code>tools/room_cull_predict.py --sweep</code></p></blockquote><p><strong>13 机位</strong>（协议 2 那七台孪生的眼点 + y135/y315 + 四台机内可达位 y27dev/y135dev/arenaW270/entryY270）逐个过 <code>actual ⊆ predicted</code>，全部 PASS；预测可见组数 1~12/16 随机位变。<strong>门本身可被证伪，两向都验过（下面两组数字是 13 机位这一档的现跑读数，不是旧 9 机位的遗留）</strong>：只把<strong>预测侧</strong>视锥收紧到 fovy=12°（光栅侧不动）⇒ 13 台里 <strong>10 台</strong>报&quot;组被剔掉却看得见&quot;（y0 6 / y27 5 / y90 3 / y270 1 / y135 1 / y315 7 / y27dev 5 / y135dev 1 / arenaW270 2 / entryY270 2，共 <strong>33</strong> 组）；强制&quot;只画背面&quot;（<code>--cull -1</code>）⇒ <strong>7 台</strong>前景跌到 0~6731 px（y180 与 y135 直接归零），被机位功率门（前景 ≥20000 px）判 FAIL——没有这条功率门时，&quot;什么都不画&quot;的机位会让不变量廉价成立。⚠ 收紧视锥必须只动预测侧：改共享的 <code>persp</code> 字典会同时挪走光栅的视锥，两边一起变窄，不变量照样 PASS，那条反证就白做了。<strong>这一行上面讲的全是离线侧</strong>，而计划 S4 那句&quot;各 yaw 下可见组集合与离线预测一致&quot;还有一台<strong>设备侧</strong>读法：ROM 在 <code>CULLGROUPS=1</code> 下打印的可见组位图（<code>src_scene/main.c:457-464</code>，<code>bit g</code> = 该组判为可能可见，组序 = <code>room_mori_r*.h</code> 末尾那行&quot;组序&quot;注释），与 <code>tools/room_cull_predict.py</code> 同机位的 <code>cgrom</code> 栏<strong>逐位相同</strong>——位图与提交面数两栏都同，九格全部相同且<strong>没有一格是 <code>ffffffff</code> 哨兵</strong>（那格是没参与本帧的房间，<code>gvis</code> 从没被写过，让 0 顶着&quot;全不可见&quot;会被当成判据读）。九台孪生的构建配方与两侧逐字相同的旋钮在 <code>evidence/cull/manifest.txt:7,62</code></p><h2 id="risk2-组盒子同源" tabindex="-1">Risk2 组盒子同源 <a class="header-anchor" href="#risk2-组盒子同源" aria-label="Permalink to &quot;Risk2 组盒子同源&quot;">​</a></h2><blockquote><p>实现:<code>gate_risk2</code>（<code>--dump-boxes</code> vs <code>include/scene/room_mori_r*.h</code>）</p></blockquote><p>16 组盒子逐字节相同、每组三角形游程和 == S1 JSON 总数、<code>R*_NG</code> 一致 —— 机内剔的是哪些盒子、剔掉多少面，先要保证它和离线量具看的是<strong>同一份</strong>几何事实</p><h2 id="risk2-每帧吞吐界" tabindex="-1">Risk2 每帧吞吐界 <a class="header-anchor" href="#risk2-每帧吞吐界" aria-label="Permalink to &quot;Risk2 每帧吞吐界&quot;">​</a></h2><blockquote><p>实现:<code>tools/room_cull_predict.py --sweep --budget</code> + <code>cmp_budget</code></p></blockquote><p>判据只认<strong>吞吐</strong>：抽查最坏机位 1898 面/5694 顶点 = 66,666 顶点/帧（NITRO v1.62 §6.2.1 的 4M 顶点/秒 ÷ 60fps）的 <strong>8.5% → PASS</strong>。在途容量 2048 面/6144 顶点（§6.2.16）按&quot;缓冲容量、非每帧上限&quot;报事实：这一档超 0 面。不剔除全量 2155 面/6465 顶点（占吞吐 9.7%）。混这两个口径是本文早期版本犯过的错，更正见 <code>docs/feasibility.md:54-72</code></p><h2 id="risk2-可达空间上界" tabindex="-1">Risk2 可达空间上界 <a class="header-anchor" href="#risk2-可达空间上界" aria-label="Permalink to &quot;Risk2 可达空间上界&quot;">​</a></h2><blockquote><p>实现:<code>--worst --worst-step 16 --worst-yaws 32</code> + <code>cmp_worst</code></p></blockquote><p>1,077,888 个<strong>可达</strong>机位（2807 个查到地板的站位 × 2 层高度 × 32 朝向 × 6 俯仰；站位高度用与 ROM 同一份 <code>col_walk_sim.Col.floorY</code> 现算，不是盲铺 y 网格）最坏 <strong>2128 面/6384 顶点 = 吞吐 9.6% → PASS</strong>，超在途容量 80 面（是否真溢出只有真机可判，<code>make RAMSTAT=1</code> 探针留着）。网格敏感性印在同一行：64/8 那档只报 2028（会假 PASS）比细网格少 62 面 ⇒ 粗网格会漏报，以细网格为准</p><h2 id="risk2-机内可见组-离线同口径预测" tabindex="-1">Risk2 机内可见组 == 离线同口径预测 <a class="header-anchor" href="#risk2-机内可见组-离线同口径预测" aria-label="Permalink to &quot;Risk2 机内可见组 == 离线同口径预测&quot;">​</a></h2><blockquote><p>实现:<code>ocr_console</code> 读 9 张剔除侧副屏 vs sweep 的 <code>cgrom</code> 栏</p></blockquote><p>九台逐位相同：位图 <code>0 7ff</code>/<code>0 7b1</code>/<code>0 80</code>/<code>b 7c5</code>/<code>8 7fd</code>/<code>0 7bf</code>/<code>0 3a1</code>/<code>1b 3c5</code>/<code>1b 240</code>，提交面数 610/360/79/641/761/548/296/739/478 也逐位相同；没有一格是 <code>ffffffff</code> 哨兵（那是&quot;本帧没画这个房间&quot;，不能当判据）。<code>cgrom</code> 而不是 <code>cg</code>：机内那个 near 就是投影的 <code>NEAR_PLANE=0.01</code>，量具保守口径 3e-5 是设计选择，用它对设备会在贴墙机位假报警（见 <code>evidence/cull/manifest.txt</code>&quot;两个位图&quot;一节）</p><h2 id="risk2-两个近平面口径自洽" tabindex="-1">Risk2 两个近平面口径自洽 <a class="header-anchor" href="#risk2-两个近平面口径自洽" aria-label="Permalink to &quot;Risk2 两个近平面口径自洽&quot;">​</a></h2><blockquote><p>实现:<code>cmp_calibers</code></p></blockquote><p>13 机位全部 <code>cgrom ⊆ cg</code>（近平面推远只许收缩，不许反超），分叉 0 处。这条是上一条的护栏：换了口径去对账，就得证明新口径确实是旧口径的子集</p><h2 id="risk2-剔除孪生-0-像素差" tabindex="-1">Risk2 剔除孪生 0 像素差 <a class="header-anchor" href="#risk2-剔除孪生-0-像素差" aria-label="Permalink to &quot;Risk2 剔除孪生 0 像素差&quot;">​</a></h2><blockquote><p>实现:<code>compare -metric AE</code>（9 对，两侧只换 <code>CULLGROUPS</code>）</p></blockquote><p>9 对全部 <strong>AE=0</strong>。被剔掉的组确实都在视锥外（相机背后 / 远平面 1500 之外 / 近平面 0.01 之内）；反向证伪是同一行：只要有一台机位剔掉了看得见的组，这里就非 0 而当场 FAIL。同机位对照：不剔除侧 y90 印 <code>GPU 1018/1018</code>（两间全量）、剔除侧 360/360 —— 少交 658 面而主屏一字不差</p><h2 id="s5-行走预测器自验" tabindex="-1">S5 行走预测器自验 <a class="header-anchor" href="#s5-行走预测器自验" aria-label="Permalink to &quot;S5 行走预测器自验&quot;">​</a></h2><blockquote><p>实现:<code>tools/col_walk_sim.py --check</code></p></blockquote><p>FAIL 行数 0 —— 出生点与边界读数与三份互不相干的实现互洽</p><h2 id="s5-被拒停点-设备-离线" tabindex="-1">S5 被拒停点 设备==离线 <a class="header-anchor" href="#s5-被拒停点-设备-离线" aria-label="Permalink to &quot;S5 被拒停点 设备==离线&quot;">​</a></h2><blockquote><p>实现:<code>gate_s5_stops</code>（<code>col_walk_sim</code> 现算 + <code>ocr_console</code> 读 <code>evidence/wall/</code> 四张副屏）</p></blockquote><p>计划那句「推向边界，被拒坐标与 COL min/max 一致」也是门而不是散文。四条拒绝分支逐个比：<code>-z</code> 撞竞技场远沿墙 <strong>(15,-3626) feet -33 hits 1（243 步）</strong>、<code>-z</code> 走出 room_0 地板 <strong>(−760,−2979) feet −193 hits 0（4 步）</strong>、<code>+x</code> 撞面 x=75 <strong>(63,−2904) feet −33 hits 1（17 步）</strong>、<code>−x</code> 踩 1 单位台阶后走出地板 <strong>(−45,−2904) feet −32 hits 0（21 步）</strong>，四台设备读数与离线仿真<strong>逐位相同</strong>；比的是位置+feet_y+wallHits（不比 moveState：它每帧在按键检查前复位，松键截图时必然 idle；<code>hits</code> 是粘住的，所以墙 vs 地板边缘两种归因靠它分开）。另加两条功率断言：离线那一点必须是<strong>不动点</strong>（再多按一步位置一字不改）且<strong>步数 &gt;0</strong>（0 步即停等于起点已在边界上，根本没走过拒绝分支）；设备走过的极值 x/z 不得越出头文件里的地板覆盖 <code>COL_WALK_*</code>。⚠ 停点是吸引子，挪 4 个单位起点仍是同一停点（实测仍 PASS）——真正证伪得了这条的是换朝向（yaw 0→180：离线 (15,−2904) vs 设备 (15,−3626)，FAIL）和把两条的截图串台（FAIL），所以夹具两套都留在 <code>--selftest</code> 里</p><h2 id="s6-本体数字门" tabindex="-1">S6 本体数字门 <a class="header-anchor" href="#s6-本体数字门" aria-label="Permalink to &quot;S6 本体数字门&quot;">​</a></h2><blockquote><p>实现:<code>tools/boss_extract.py</code></p></blockquote><p><code>ALL PASS</code> —— 699 顶点/440 三角形、<code>&lt;Array Count&gt;</code> 守恒、limb 归属与剔除位对账。<strong>但这一行只证&quot;网格解出来了&quot;，不证&quot;屏幕上看得见&quot;</strong></p><h2 id="s8e-青年加农-flex-骨架数字门" tabindex="-1">S8e 青年加农 Flex 骨架数字门 <a class="header-anchor" href="#s8e-青年加农-flex-骨架数字门" aria-label="Permalink to &quot;S8e 青年加农 Flex 骨架数字门&quot;">​</a></h2><blockquote><p>实现:<code>tools/boss_extract.py object_gndd --tex</code></p></blockquote><p>S8 计划里&quot;接 <code>object_gndd</code> 取真实步行形态&quot;这一格的前置门。此前 <code>--stats</code> 两条现红（<code>limb DL 内 G_MTX/G_POPMTX == 0</code> FAIL 4 条、<code>走查零 issue</code> FAIL 8 条），根因不是&quot;提取器有 bug&quot;而是<strong>那条判据本身对 Flex 骨架不成立</strong>：<code>object_gnd.xml</code> 的 <code>&lt;Skeleton Type=&quot;Normal&quot;&gt;</code> 才允许&quot;DL 内没有矩阵切换&quot;，<code>object_gndd.xml</code> 是 <code>Type=&quot;Flex&quot;</code> —— 它与 Link 的 <code>object_link_child</code> 同构， limb DL 头部 LOAD <strong>邻居 limb</strong> 在段 0x0D 的 Mtx 槽烘关节顶点，再换回自身，F3DEX 在 <code>G_VTX</code> 那刻就用当时的矩阵变换顶点。于是这一行改判据为三条：<code>G_MTX 全部解到段 0x0D 合法槽</code>（8/8 条记账，<code>G_POPMTX</code> 0 条）、<code>槽表数量 == 有网格 limb 数</code>（22/22，槽号 = 只算有网格 limb 的前序绘制序）、<strong><code>有切换的 limb DL 收尾矩阵 == 自身</code></strong>。第三条是为「槽表整体错一格」这一类最典型错法专门加的：它的功率不是讲出来的，是钉在 <code>--selftest</code> 里的（见下面「纪律 Flex 槽表负对照」那一行）—— 键整体 <code>+1</code>、整表反转、逐槽右移一位这三种错法都把关节顶点挂到邻骨名下，前两条判据<strong>照样 PASS</strong>（槽号全都解得出，一个 issue 都不报），只有第三条在 4/4 条切换 limb（9/10/11/12）上转红。实测归属读数：23 limb / 22 条有网格 / 1131 顶点 / 570 三角形，<strong>38 个关节顶点</strong>（在别的 limb 矩阵下载入）、<strong>42 个三角形三个顶点的归属不全相同</strong>；切换来源 limb = <code>{9→14, 10→14, 11→10, 12→14}</code>（limb 14 是躯干枢纽，limb 11 的邻骨是它的父 limb 10），与 Link 侧 <code>THIGH→WAIST</code>、<code>SHIN→同侧 THIGH</code> 那批同形。另加一条两通道互验：<code>geometry</code>（S6/boss_pose 一直在读的那份，顶点按数组条目去重、load 序）与 <code>attributed</code>（新通道，顶点按 <code>(条目, 归属 limb)</code> 展开、三角形引用展开表）必须逐 limb <strong>三角形顶点键逐条相同</strong>，且归属只许落在有网格 limb 上（段 0x0D 的槽只发给 <code>dList != NULL</code> 的 limb）。同一份工具对 <code>object_gnd</code> 回归：699/440 一字未变、Standard 分支仍走&quot;矩阵类命令 == 0&quot;那条原判据 ⇒ 加 Flex 通路没有把已验收的那只放开。<strong>纹理读数</strong>（这一格只报预算，上不上设备是 S8f 的范围决定）：骨架可达 DL 里 25 张图、25 张全部真被三角形画到，1 页 TLUT（<code>seg6:0xECB8</code>，entries=256，载入 2 次），转 NDS 侧 A1B5G5R5 需 纹 10336 B + TLUT 512 B = <strong>10848 B = 256 KB VRAM 的 4.1%</strong>；描述符自洽门（<code>bytes == w*h*bpp</code> 且 <code>dxt == CALC_DXT</code>，与 S2 房间 B1 同式）25/25 全过。一处 ROM 事实要说清：<code>limb 14</code> 有 <strong>1 张</strong> CI 8b 32×16 的图像地址是 <code>0x08000000</code> —— 段 8 + 偏移 0，即由绘制器 <code>gSPSegment</code> 现填的运行时段（与本对象 24 张段 6 图同描述符，是一张配色变体），静态解不出基址；因此那条地址判据写成&quot;段 6 <strong>或</strong> 运行时段+偏移 0&quot;，偏移非 0 的别的段号仍是 FAIL（房间 S2 为这类错单独建过门：基址解错会静默解成噪声而数量守恒一项不响）。<code>img_w</code>（<code>G_SETTIMG</code> 的 width 域）在两只对象与两间房里读出的都是 1 —— 那是 ROM 事实（这些 DL 用 LOADBLOCK 上传，宽度域没填，尺寸权威在 <code>G_SETTILESIZE</code> 的 10.2 定点 ul/lr），不是解错位域。读数出处：<code>python3 tools/boss_extract.py object_gndd --stats</code>（槽表与逐 limb 归属）、<code>--tex</code>（纹理预算）、<code>--emit</code>（落 <code>data/object_gndd.json</code>，S8f 烘焙与离线预测器读它）、<code>--selftest</code>（负对照）。这一格<strong>没有截图</strong>：它量的是提取器，设备侧还没有 gndd 的任何通路（S8f）。</p><h2 id="s6-本体剪影门" tabindex="-1">S6 本体剪影门 <a class="header-anchor" href="#s6-本体剪影门" aria-label="Permalink to &quot;S6 本体剪影门&quot;">​</a></h2><blockquote><p>实现:<code>tools/boss_screen_predict.py</code> + <code>gate_boss</code></p></blockquote><p>计划 S6 那格「竞技场里看得见幻影加农本体」从人眼判据改成逐像素判据。取法：<code>ROOMS=0</code> 时清屏色是洋红（<code>src_scene/main.c:257</code>）、<code>LINKDRAW=0</code> 关掉 Link ⇒ <strong>非洋红像素即本体剪影</strong>，不必按颜色认几何；离线侧读 <code>boss_gnd.h</code> 的 699/440，按 <code>draw_boss.c</code> 那条 <code>T·Ry·S</code> 链同式同序换到世界系、脚底用与 ROM 同一份 <code>colFloorY</code> 现算，再走协议 2 那<strong>同一只</strong>光栅。两台只换机位：站位 (15,−2900) yaw 0 ⇒ <code>预测 296 实机 284 位移 2,0 零位IoU 0.425 位后IoU 0.801</code>；站位 (−300,−3300) yaw 90 ⇒ <code>预测 411 实机 388 位移 2,1 零位 0.407 位后 0.796</code>。判据四条：两侧像素数各 ≥150（防&quot;整块在视锥外&quot;廉价通过）、扣位移后的 IoU ≥0.75、<strong>位移本身当被报出的量</strong>且须在 |dx|≤4/|dy|≤2 内、门独立重推 IoU 必须与量具结论词一致（12 个夹具在 <code>--selftest</code>：实机 0 px / 位移 9 / IoU 造低 / 结论词脱钩 / 交集两个推法不齐 / tag 串台 全判 FAIL）。<strong>为什么摆位错与模拟器错位分得开</strong>：yaw=0 时世界 x 的错几乎是纯屏幕 dx、yaw=90 时几乎是纯深度，两台最优位移都是 dx=2 ⇒ 是屏幕平移不是摆放错，量级正是偏差 1 那一层（本体两个机位各加一个实测点）。残差全部在边界上：y0 的 38 个&quot;仅CPU&quot;与 26 个&quot;仅GPU&quot;<strong>逐个</strong>距对方剪影 ≤1.5 px（两侧最大都是 1.41 px），y90 是 56/57 与 34/34 —— y90 那 1 个越界点在 <strong>2.00 px</strong>，所以这一句不许写成&quot;全部 ≤1.5&quot; ⇒ 是填充规则的亚像素边界，不是形状错（对照：房间那条门同样只有 50~76% 逐位全等）。反向验过四条（都在内存里改摆放，验收 ROM 与它的输入未被碰过）：实机侧剪影清空（＝本体一像素没画上）⇒ <code>实机 0 px</code> FAIL；把本体沿世界 x 挪 <strong>60 raw</strong>（约 6 px）⇒ 位移 −6,3 越带且位后 IoU 0.066 FAIL；朝向 <code>facing 0→90</code> ⇒ 位移 5,−2 越带且 IoU 0.402 FAIL；尺度 <code>GLSCL ×1.2</code> ⇒ 位移 2,4 越带且 IoU 0.599 FAIL。<strong>这条门的分辨率就是那个位移带</strong>：挪 20 raw（不到 4 px）仍落在带里照样 PASS —— 它管的是&quot;摆错一档/朝向错/尺度错&quot;，不管亚 4 px 的偏移（那正是偏差 1 允许模拟器自己有的余量）。实物与旋钮在 <code>evidence/boss/</code></p><h2 id="s6-本体深度归属门" tabindex="-1">S6 本体深度归属门 <a class="header-anchor" href="#s6-本体深度归属门" aria-label="Permalink to &quot;S6 本体深度归属门&quot;">​</a></h2><blockquote><p>实现:<code>tools/boss_depth_gate.py</code> + <code>gate_boss_depth</code></p></blockquote><p>上面那台剪影孪生是 <code>ROOMS=0 LINKDRAW=0</code> 的：它证摆放/尺度/朝向对，但帧里没有别的东西能挡本体，所以<strong>量不到深度</strong>。而&quot;本体走的是与房间/Link 同一条深度路&quot;在 NDS 上是个真实存在的错法（偏差 3：无 per-poly z-write 控制，本体可以一直盖在最上层），此前只有人眼凭据。取法是<strong>三台同旋钮孪生只差被检那一位</strong>：<code>full</code>(BOSS=1 LINKDRAW=1 ROOMS=1) / <code>noboss</code>(只差 BOSS=0) / <code>linkonly</code>(ROOMS=0 ⇒ 洋红底，非洋红即 Link 剪影)，<strong>设备差异 = full XOR noboss = 本体在成品帧里真正贡献的那批像素</strong>（房间先画、Link 第二、本体最后，所以差异只可能是本体赢得深度测试的那些像素）；离线侧把房间与本体喂进<strong>同一只</strong>光栅、同一份 z-buffer，取 <code>owner==boss</code> 再挖掉 Link 剪影。远机位（站出生点 yaw0）的 full <strong>就是验收锚点 <code>83bd4dfa</code> 本身</strong> —— <code>NAME=</code> 不改一个字节，所以这一行量的不是诊断孪生，而是交付的那份 ROM。读数：远机位 <code>差异 279 允许 296 位移 2,0 零位 0.420 → 位后 0.786 遮挡 0 落在Link上 0</code>，近机位（<code>STARTZ=-3200</code>，朝本体走 300 raw）<code>差异 1514 允许 1613 位移 2,0 零位 0.663 → 位后 0.888 遮挡 166 落在Link上 0</code>。判据五条：成品差异与离线允许集各 ≥150 px、<strong>Link 挡住本体 ≥100 px</strong>（这条是功率）、本体画进 Link 剪影内 ≤12 px、位移带 |dx|≤4/|dy|≤2、位后 IoU ≥0.75；门另加两条：整行<strong>至少一台</strong>遮挡 ≥100（否则两格都退化成&quot;没重叠&quot;也照样绿），以及三条自指（位后 ≥ 零位、<code>允许-缺口 == 差异-越界</code>、IoU == 交/并）。<strong>为什么两个机位都要，是量出来的不是讲出来的</strong>：把&quot;本体无视深度地整块刷进成品帧&quot;这一招在近机位 ⇒ <code>落在Link上 166 px</code> FAIL，在远机位 ⇒ 那个数<strong>照样 0</strong>（Link 与本体在屏幕上根本不重叠），所以远机位默认档当场 FAIL，只靠显式 <code>--minoccl 0</code> 降级为可见性证据。其余反证：成品里没本体（full=noboss）⇒ FAIL「本体只贡献 0 px」（不是&quot;两侧都 0 ⇒ IoU 0/0 蒙过&quot;）；本体在屏幕上摆错 20 px ⇒ 位移 6,-1 顶爆带、位后 IoU 0.194 FAIL；拿错机位的 Link 剪影去挡 ⇒ 远机位读数一字不变（再一次证明它量不到深度）。真图的深度归属干净到可以把容差压到 0：<code>--maxover 0</code> 真图照样 PASS（遮挡那 166 px 一个像素也没漏到 Link 身上）。缺口 142/越界 43 是剪影轮廓那一圈，与恒等式 <code>1613-142 == 1514-43 == 1471</code> 同时成立 ⇒ 不是集合错。<strong>这条门只覆盖&quot;本体 vs Link&quot;一侧</strong>：&quot;本体 vs 房间&quot;在本场景是<strong>结构性无功率</strong>，不是没验而是没有可验机位 —— 站位扫描（2026-10-05，walk box 内 160 机位、本体入视的 52 个）里房间吃掉本体的比例是<strong>双峰</strong> 0.0%/100.0%、介于两者之间的机位 0 个，而 100% 那批的遮挡者全是贴脸墙（单块 room_1 opa 三角形盖 50.7%~100% 屏幕、最近顶点离眼 0.045~0.178 world unit；hide90 的遮挡者是 arena 八边墙面 x≈-351~-362 raw，而眼点在 x=-390 —— 相机已在墙外，量的是墙背面），属偏差 4 那类退化机位。两台合法机位因此都印 <code>本体单画 == 房间里的可见像素</code>（296/296、1779/1779，<code>房间遮挡 0.0%</code>）：boss 站在 arena 中央、身后才是墙，面前只有地面。曾为此加过 <code>--mode occluded</code>（判据反转 + <code>--minhiding</code>/<code>--maxhidden</code>）并建了第三组三台孪生（hide90），实测 FAIL 且那 386 px 全部落在设备自己已画前景的像素上（与&quot;只有离线画了&quot;的 3079 px 交集 0）⇒ 它既不能当 PASS 用也不能当&quot;本体不走深度&quot;的证据，<strong>已删</strong>（空判据机器）；三张 hide90 图与旋钮留在 <code>evidence/boss/manifest.txt</code> 当&quot;为什么删&quot;的凭据。18 个夹具在 <code>--selftest</code>（遮挡 3 px / 落在Link上 200 px / 差异 0 / 允许 20 / 位移 7 / IoU 0.500 / 缺口改 200 破坏交集恒等式 / 位后低于零位 / 结论词脱钩 / tag 串台 / 行读不全 / 旧行格式缺新字段 / <code>房间遮挡</code> 或 <code>本体单画</code> 单独改数破坏 <code>允许+遮挡 == 单画×(1-遮挡率)</code>，全须 FAIL）。六个 md5 已逐位复现（五台进 <code>--rebuild</code>，第六台与锚点同字节故不重复占时间），实物与旋钮在 <code>evidence/boss/</code></p><h2 id="s6-xlu-层归属-深度门" tabindex="-1">S6 xlu 层归属/深度门 <a class="header-anchor" href="#s6-xlu-层归属-深度门" aria-label="Permalink to &quot;S6 xlu 层归属/深度门&quot;">​</a></h2><blockquote><p>实现:<code>tools/xlu_depth_gate.py</code> + <code>gate_xlu_depth</code></p></blockquote><p>「xlu 层仍未验过」的替换品。room_1 的 xlu 层只有 2 个三角形（顶点数组 D520 的 4 点，y 两个都是 −33 raw），取<strong>同批构建</strong>的七台孪生、只差被检那一位：成品(full)/去 xlu(opa)/只 xlu/只 xlu 且纹素 alpha 全置 1(<code>TEXOPAQUE=1</code>)/洋红诊断底(<code>ROOMS=0</code>)/成品与去 xlu 各再一台 <code>FOG=0</code>(RF/RO，拆雾用)。三个量各钉一件事——<code>dose</code>=只 xlu XOR alpha 全置 1=<strong>8523 px</strong> 是这块层在设备上真正画到的地方（比的是同机位两台之间，免疫雾色碰撞），<strong>100% 落在离线 footprint 8980 px 内</strong>、位移 (1,1) 后 IoU <strong>0.902</strong>；<code>net</code>=成品 XOR 只 opa=<strong>689 px</strong> 是交付帧里这块层真正贡献的像素，判据 <code>net ⊂ dose</code>（689/689）；亮度中位 baked 18 → forced 4 钉住&quot;那 1 bit alpha 管明暗、不管画不画&quot;，同时钉住 <code>TEXOPAQUE</code> 没退化成空操作（改前它确实是空操作：旧 ROM b7e5cac7 的 xluopaque 帧与 41c1b47d 的 xlu 帧逐位相同）。副屏另侧印证提交量：1018/1018、opa 少 2 块(1016/1018)、xlu 侧正好 2/1018（这三个数的出处是副屏 OCR 存档 <code>evidence/xlu/manifest.txt:70,75,130</code>；快门不重读这一栏，要复核就按那份清单里的命令重跑 OCR），且 xlu 与 xluopaque 的副屏<strong>逐字节相同</strong> ⇒ <code>TEXOPAQUE</code> 只改纹素不改提交。机位是<strong>离线扫出来的有边距</strong>档（footprint 距屏幕下沿 81 px）且<strong>七台同一批 make</strong>：上一版拿纹理修复前的三张与修复后的两张做差分，量出 net=8452 px 的假&quot;层盖住地面&quot;；p25 那档（net 11 px）与行走机位（余量 0 px）都因空判据不作判据，<code>--minraw 500 / --mindose 500 / --minnet 200</code> 就是这三道闸。深度那一项<strong>只报数不判，且这是量出来的</strong>：与竞技场地面共面（同为 y=−33 raw），离线在同一批像素上量 <code>|opa 距离 − xlu 距离| ≤ 1.71 个 raw 单位</code>，而 NDS 深度 20.8 定点<strong>一格就是 4 个 raw</strong> ⇒ 同一个深度格子；设备可见的 689 px 与离线&quot;该由 xlu 赢&quot;的 853 px <strong>零交集</strong>（±6 px 容差下仍 0），却 659/689 落在&quot;opa 更近&quot;那批上 —— 连&quot;设备做了严格 LESS 测试&quot;这个假设都被否掉，所以偏差 3 的形状是<strong>共面 ⇒ 平局不可判</strong>，不是&quot;没测&quot;，也不是&quot;层盖住了地面&quot;。门把共面前提本身钉住（<code>|Δ| ≥ 4 raw</code> 即 FAIL 并要求重建判据），另加自指（覆盖数不许大于 net、包含率与 IoU 不许 &gt;1、离线划分<code>opa更近 + xlu更近 ≤ footprint</code>、结论词由判据推出、容差窗必须等于门常量、<code>--gen</code> 空则 FAIL）。<strong>&quot;平局不可判&quot;这句不欠雾一份解释</strong>：<code>FOG=0</code> 那两台重做同一套 XOR，得到的仍是同一批像素 —— 无雾 net 也是 689 px、<strong>对称差 0</strong>（条带行 116~131、列 59~219，在本体与 Link 剪影之外），所以 net 不是&quot;画了但等于雾色&quot;那种读数，<code>net ∩ 离线获胜集 = 0</code> 也不能推给雾；这两台因此是硬判据的一部分（对称差 ≠ 0 或无雾 net &lt; 200 px 即 FAIL，量具没拿到无雾帧时该栏印 -1 ⇒ 整行读不出来 ⇒ FAIL），23 个夹具在 <code>--selftest</code>。Link 剪影门另加 19 个夹具（<code>cmp_linksil</code>），见下面「S5 Link 剪影门」那一行。</p><h2 id="s5-link-剪影门-走到位的机位" tabindex="-1">S5 Link 剪影门（走到位的机位） <a class="header-anchor" href="#s5-link-剪影门-走到位的机位" aria-label="Permalink to &quot;S5 Link 剪影门（走到位的机位）&quot;">​</a></h2><blockquote><p>实现:<code>tools/actor_silhouette.py gate</code> + <code>gate_linksil</code></p></blockquote><p>量具文件头钉死的那两台（<code>lkP1</code>/<code>lkP0</code>）机位是<strong>出生点</strong> (15,−2900) yaw0 pitch−5，于是&quot;Link 可行走&quot;这条腿在走到位之后一直只有设备自报的 <code>link px 128,172-128,100</code> 两点读数 + 人眼；而那两点读数已被它自己的证据否掉（两个&quot;理想点&quot;与真剪影<strong>下沿</strong>差 +4~5px、上沿只差 0.3px —— 掠射刀锋三角形使剪影下沿比理想脚点低几行，量具把那行印成&quot;差得多的那个就是它不能当判据的证据&quot;）。这一行补逐像素那条：两机位各一台纯色底孪生（<code>ROOMS=0 BOSS=0</code>，只差 <code>LINKDRAW</code> 一位）—— wa33 = (15,−3033) yaw0 pitch9，wb39 = (15,−3039) yaw21 pitch9 <code>LINKYAW0=21</code>（朝向按 <code>180-yaw+LINK_YAW0</code> 仍是 180，所以 wb39 单独把&quot;相机转了但场景没换&quot;这一件事纳入逐像素判据）。读数：<code>la33 预测 1663 px / 实机 1598 px 位移 -1,-2 零位 0.737 → 位后 0.878 一圈 100.0/100.0 最差边 上沿+4</code>、<code>lb39 预测 1707 / 实机 1656 位移 -2,-2 零位 0.740 → 位后 0.906 一圈 100.0/100.0 最差边 上沿+4</code>。判据六条各配独立阈值（两侧像素数 ≥800 防空功率、位后 IoU ≥0.80、一圈包含双侧 ≥99.0%、最差边 ≤6px、位移带 |dx|≤3/|dy|≤4、跨度必须是预测的一半到一倍之间——off 图多关一个元素时跨度会翻倍以上）；外加三条&quot;不许蒙&quot;的规则：任何字段是 <code>-1</code> 哨兵（量具中途 return，那条判据压根没量到）即 FAIL、<code>最差边 none</code> 即 FAIL（四边一条都没比＝机位无功率）、而<strong>负边偏移是合法读数不是哨兵</strong>（<code>上沿-1</code> 必须 PASS，这条本身在夹具里）；<code>--conv origin</code>（DS 像素规则假设）在 la33 上另测 <code>零位 0.786 → 位后 0.898</code>、最差边从 +4 收到 +3，优于 center 的 <code>0.737 → 0.878</code>，没有新证据推翻文件头那条记录。<strong>这一行不判绝对摆放，且这是量出来的不是推的</strong>：<code>--camx/--camz</code> 不传时取演员自己的位置，而 ROM 的相机正是绕玩家 orbit 的，于是&quot;演员站在世界里哪一格&quot;在该量具里是<strong>规范自由度</strong> —— 实测把 <code>--x</code> 改 3 单位并同时把 <code>--feet</code> 改 10 单位，读数一字不变（0.737 / -1,-2 / 100.0,100.0 / PASS）。把相机中心钉死（<code>--camx 15 --camz -3033</code>）后测出灵敏度 <strong>≈0.8 px/世界单位</strong>：演员沿视线后移 5 单位 ⇒ 常量 dy −2→−5、零位 IoU 0.737→0.622（FAIL），后移 10 单位 ⇒ dy −9、IoU 0.556 ⇒ 位移带 ±4 的实际功率下限约 <strong>5 世界单位</strong>（≈0.7~0.8 px/单位）。站位本身由 <code>pos</code>/<code>walk x[..] z[..]</code> 读数那行（S5 被拒停点）与带房间时房间相对他滑动的那些图负责。两台 off 图<strong>逐字节相同</strong>（整张 49152 px 只有一种颜色 255,0,255＝<code>ROOMS=0</code> 的洋红诊断底），这不是省事而是对照组自检：<code>ROOM=0 BOSS=0 LINKDRAW=0</code> 什么都不画，机位转多少都不改变它——一旦哪天 off 那台还画着别的东西，两张图就不再相同。<code>--feet -33</code> 有出处：设备自己在落点用 <code>colFloorY</code> 重探（<code>src_scene/main.c:284-290</code> 那条分支），两处都读回 −33。19 个夹具在 <code>--selftest</code>（实机 0 px / 预测哨兵 / 只有一侧量到一圈 / 最差边 none / 位后 IoU 0.500 / 位后低于零位 / 位移 -2,-6 与 -5,-2 越带 / 一圈 95.0 / 边 +9 / 实测跨度 160 / 结论词脱钩 / <code>常量 checked</code>（实例性质变了必须连本行与文档一起改）/ tag 串台 / 行读不全 / 啥也没打印，全须 FAIL；<code>最差边 上沿-1</code> 是唯一正例）。四台 ROM <code>lkLa33a 4c2f2908</code> / <code>lkLa33b 3392a421</code> / <code>lkLb39a 554aa44e</code> / <code>lkLb39b 2df64bf9</code> 进 <code>--rebuild</code>，且是<strong>先证再锚</strong>（同旋钮 <code>rm -rf build/&lt;NAME&gt;</code> 连编两遍逐字节相同才写进名单）；图片、配方、副屏 OCR 逐行读数与功率实测在 <code>evidence/linksil/manifest.txt</code>。<strong>这批图在 2026-10-08 重拍过，起因是名字不是画面</strong>：归档那五张的文件名前缀是 <strong>PNG 自己的 md5</strong>，而站点与画廊的口径是「前 8 位 = 画它那份 ROM 的 md5」，两句对不上——<code>lkLa33a</code> 今天的字节是 <code>4c2f2908</code>，图却叫 <code>86236da7…</code>。按今天的四台整套重拍：两张上屏的<strong>前景数一字不变</strong>（la33 1598 / lb39 1656），差的只是 867/887 个<strong>彩色</strong>像素（正是 <code>LINKTEX</code> 默认翻成 1 的可见效果，剪影与深度都不动），S5 门在原判据下的读数与旧记录逐格相同（la33 位后 0.878、lb39 0.906、一圈 100.0/100.0），两台 off 图<strong>仍逐字节相同</strong>（对照组那条自检在新图上重跑了一遍）。旧五张移到 <code>evidence/linksil/stale/</code>，新图按 ROM 前缀命名。<strong>这一笔不改任何判据，改的是证据的身份证</strong>。<strong>这一批是重做的</strong>：第一批四张图（lkWa33a/lkWa33b/lkWb39a/lkWb39b）按记录的配方重编四台全对不上 md5，且重编的 <code>ROOMS=0</code> 台清屏是洋红而归档图是雾色、归档那次副屏印 <code>GPU 408/408</code> 而 <code>ROOMS=0</code> 应印 <code>0/0</code> ⇒ 那四张图出自一台与记录配方不同的 ROM（正是 <code>tools/capture_screen.sh</code> 规则 1 警告过的&quot;图与 ROM 的对应关系没钉住&quot;，只是方向相反：不是截错窗口，是记错配方）。图本身自洽（位后 IoU 0.873）也不能留——出处不可复现的证据不是证据。教训两条已写进 <code>evidence/linksil/manifest.txt</code> 末尾：先证再锚；图与读数出自同一瞬间同一台（<code>SCREEN=both</code>）且要用副屏那行 <code>GPU 0/0</code> 与&quot;这张图是纯色底&quot;互相印证</p><h2 id="s8-link-动画逐帧门" tabindex="-1">S8 Link 动画逐帧门 <a class="header-anchor" href="#s8-link-动画逐帧门" aria-label="Permalink to &quot;S8 Link 动画逐帧门&quot;">​</a></h2><blockquote><p>实现:<code>tools/anim_silhouette_gate.py gate</code> + <code>gate_anim_frames</code></p></blockquote><p>上面那台静态门在 bind pose 下有个结构性盲区：相邻 limb 的累积矩阵几乎重合，顶点挂错 limb 时屏幕上看不到缝，只有动起来才撕得开。所以这一门判的是「(ROM 帧号, 离线帧号) 成对截图」×「逐顶点整数变换」，九帧各判一遍再要求汇总行 <code>ANIMSIL-BATCH 9 帧 ⇒ PASS</code>（S8c 那五帧是步行 0/10/20 + 待机 0/14，S8d 追加攻击段四帧 1/4/8/13）。取法：十台同批孪生只差 <code>ANIMSEL</code>/<code>ANIMFRAME</code> 两位（<code>ROOM=0 BOSS=0 LINKBBOX=1 CAMDIST=90.0 CAMPITCH=12.0 STARTZ=-2900</code>），第 0 台 <code>agBlank</code> 另关 <code>LINKDRAW</code> 当纯色底。<strong>判据第 0 项不是像素</strong>：设备把 <code>animXform</code> 那三行整数运算自印成逐顶点逐轴求和（<code>lksum</code>，<code>src_scene/link_rigid.c:linkAnimSum</code>），离线 int64 同式复刻必须与它<strong>逐位相等</strong>；这一项在九帧全部读作「校验和 一致」，中间量实测 |Σ m·p| ≤ 8.2e7，距 2^31 还有约 26 倍余量（这余量正是&quot;同式复刻&quot;能逐位比的前提，门把 <code>i32</code> 读数本身钉成 <code>0 &lt; i32max &lt; 2^31</code>）。像素那五项在九帧的读数：<code>agW0 IoU 0.901</code>、<code>agW10 0.892</code>、<code>agW20 0.881</code>、<code>agI0 0.874</code>、<code>agI14 0.886</code>、<code>agA1 0.895</code>、<code>agA4 0.905</code>、<code>agA8 0.900</code>、<code>agA13 0.886</code>；一圈包含九帧都是 <code>100.0/100.0</code>；下沿偏差步行/待机 <code>+0.0/+0.0/+1.0/+1.0/+1.0 px</code>、攻击 <code>+0.0/+0.0/+0.0/+1.0 px</code>；顶点盒差 <code>0</code>；抓图常量 <code>-1,-2</code>（<code>agI0</code> 与攻击四帧为 <code>-2,-2</code>，<code>agA4</code> 为 <code>-2,-1</code>）；脚底相对 <code>colFloorY</code> 九帧全 <code>+0.000</code>、穿地全 <code>+0.000</code>。阈值：像素数两侧各 ≥800 且比例落在 0.5~1.5、IoU ≥0.75、一圈双侧 ≥98.0%、下沿 |Δ|≤3 px、顶点盒差 ≤2、常量在 ±4 窗内、脚底 |Δ|≤0.05 模型单位、穿地 ≥−0.5、<code>顶点盒差 -1</code>（ROM 没带 <code>LINKBBOX</code>＝剪影没有出处）按 FAIL。<strong>&quot;脚在动而整体也在走&quot;有机器证据</strong>：九帧设备自报位置 z 为 −2943 / −2976 / −2979 / −2919 / −2979 / −2982 / −2982 / −2979 / −2982，<code>feet_y</code> 恒 −33，不是原地摆姿势。<strong>攻击那四帧不是随手挑的</strong>：<code>1</code> 与 <code>4</code> 落在起手段的命中窗内（原作窗口由 <code>D_80854190[PLAYER_MWA_FORWARD_SLASH_2H]</code> 的 <code>{1, 4}</code> 定，见 <code>evidence/anim/attack-selection.md</code>），<code>8</code> 是收势段跳帧序列 f0,f1,f3,f4,f6,f7,f8 的第 4 格（验&quot;跳帧后表索引仍对&quot;），<code>13</code> 落在 morph 尾（混合权重 0.50）。<strong>这条门量不到&quot;哪一帧&quot;，且这是量出来的</strong>：可辨识度栏把该段其它帧当竞争者、各允许在自己的最优位移下比，逐帧给「秩 + 本帧差渲 + 段内最小对称差（分立）」。实测分立 = 31 / 63 / 34 / <strong>2</strong> / 52（步行+待机）与 185 / 195 / 243 / <strong>52</strong>（攻击），而 CPU 预测对 GPU 的本底差渲是 125~206 px ⇒ 像素只够证明&quot;这张图是该段的某帧&quot;，帧号身份靠 <code>lksum</code> 与设备自印 <code>s_frame</code>，后者与画它的是同一段代码所以<strong>不算独立证据</strong>。±1 帧的错位三条通道都抓不住 —— 这条限度写在 <code>evidence/anim/manifest.txt</code> 与本文里，不拿阈值糊过去；<code>分立2</code> 是合法读数不是故障，夹具专门留了它。<strong>攻击帧的负对照把&quot;像素看不见归属错&quot;这件事又证了一遍</strong>：把顶点 #363 从 limb 10 改挂到 limb 11，剪影被推掉 77 px（步行帧那条只推 14 px），五个像素通道仍全绿（IoU 0.789、一圈 99.8/99.5、下沿 +0.0、盒差 0、秩 1/15），红的只有校验和；隔 9 行的改帧号则七条通道一起红（IoU 0.612、下沿 +13.0 px、盒差 15）。<strong>量具那十台把段和帧钉死，所以&quot;按下去到底进不进这个段&quot;要另证</strong>：载体 <code>lkKeys.nds</code>（副屏带 <code>keys cur/new</code>）不传 <code>ANIMSEL</code>/<code>ANIMFRAME</code>，只改 <code>SETTLE</code> 就读出梯子 <code>anim 0/2 → 2/5 → 2/14 → 0/2</code>（进段、放到 morph 尾、回待机，<code>view pitch</code> 四档全程 12 没被扯动），对照组按 NDS A/B 只让 pitch 变 24/0 而 <code>anim</code> 留在 0/7 —— 这就是移植里攻击挂 <strong>X</strong>、A/B 保持相机俯仰的实测依据（原作这一档是 A，属有意偏离，见 §5 偏差 7）。22 个夹具在 <code>--selftest</code>（校验和读成 <code>差[700, 67808, 22111]</code> / 一圈 97.0 / 下沿越带 / 顶点盒差 <code>-1</code> / 常量 <code>-2,-35</code> / <code>i32</code> 顶到 2^31 / 秩 <code>-1/-1</code> / 结论词脱钩 / tag 与「段帧」对不上 / 行读不全 全须 FAIL；两条正例含 <code>分立2</code>）。十台 ROM 进 <code>--rebuild</code>（先证再锚），图片、十条 make 配方、快门命令、副屏 OCR 逐行读数、两条攻击负对照与上面那张按键实测表都在 <code>evidence/anim/manifest.txt</code>；选片、命中窗与素材脏数据在 <code>evidence/anim/attack-selection.md</code></p><h2 id="s8-动画门负对照" tabindex="-1">S8 动画门负对照 <a class="header-anchor" href="#s8-动画门负对照" aria-label="Permalink to &quot;S8 动画门负对照&quot;">​</a></h2><blockquote><p>实现:<code>tools/anim_silhouette_gate.py negctl</code> + <code>gate_anim_negctl</code></p></blockquote><p>计划对这一门写的是&quot;人为改错就 FAIL&quot;，落地成两项反证且<strong>都实跑</strong>：① 把顶点 #107 的 <code>refLimb</code> 从 limb 5 改挂到 limb 4（选点规则是轮廓带上投影位移最大者，打印出来供人核，不是挑对自己有利的）⇒ 该顶点投影位移 20.6 px、剪影变 14 px，但 <code>IoU 0.896 一圈 100.0,100.0 下沿 +0.0px 顶点盒差 0 指认 秩1/29</code> <strong>五项像素判据全绿</strong>，只有校验和红：<code>差[700, 67808, 22111]</code>。② 拿 1/25 帧的离线预测去对实机 1/10 那张图 ⇒ <code>校验和 差[-259024, 71114, 140950]</code>，另加 <code>一圈 97.0,99.3</code>、<code>顶点盒差 2</code>、<code>秩 21/29 差渲 376 分立 92</code>（最优竞争者是 1/10、1/11、1/9，差 197 px &gt; 容 25）。① 那组数字同时是<strong>像素通道的功率上限</strong>，所以门把它写成双向判据：<code>ANIM_NEGS</code> 除必需命中词外还有禁止命中词，改归属那次必须<strong>不出现</strong>「一圈核对 / 门限 / 下沿不符 / bbox / 抓图常量 / 可辨识度: 段内有别的帧」——哪天像素也能看见这种错了，这一行会当场红，那是&quot;限度变了&quot;的信号而不是回归（内部顶点挂错 limb 时并集轮廓只动 1 px：实测 #123 模型 Y 动 2.88、投影动 25 px、掩膜变 1 px，那种错归 S8a 的骨长守恒不变量管，不归剪影）。汇总行 <code>ANIMSIL-NEG 每帧都 FAIL ⇒ PASS</code>，且注意 <code>negctl</code> 的退出码是<strong>反的</strong>（rc=0 表示&quot;每帧都红了&quot;＝对照有效），门里按这条判而不是照抄普通档符号</p><h2 id="s8f-本体动画逐帧接地门" tabindex="-1">S8f 本体动画逐帧接地门 <a class="header-anchor" href="#s8f-本体动画逐帧接地门" aria-label="Permalink to &quot;S8f 本体动画逐帧接地门&quot;">​</a></h2><blockquote><p>实现:<code>tools/boss_frame_gate.py check</code></p></blockquote><p><code>docs/boss-anim-bake.md</code> 那六条自验只证明 <code>include/scene/boss_anim.h</code> 那张表<strong>离线自洽</strong>，它不碰设备。这一门把表上机之后的读数拿回来对：量具自己解析那张头文件、在 Python 侧<strong>独立复刻</strong>机内那条整数变换（<code>(m[3k]·x+m[3k+1]·y+m[3k+2]·z)&gt;&gt;10 + m[9+k]</code>，再 <code>/65536</code>），然后拿 <code>tools/ocr_console.py</code> 从归档副屏里抠出的机内自印值比。四件事一起判：① 机内自印的 <code>form/seg/frame</code> 必须等于归档名单点名的那一台 —— 不等就是&quot;这张图与它的构造配方分家了&quot;，判据当场失效；② <code>foot</code>（该帧全身最低点 + 其归属 limb）到 <code>%.4f</code> 一致，容 <code>5e-5</code>，即<strong>不超过 OCR 自己的显示位宽</strong>（这条门的分辨率就是副屏那四位小数，比它小的差它判不了，也不假装判得了）；③ <code>attr == 0</code> 且 <code>nv</code>/<code>ntri</code> 等于 rig —— <code>attr</code> 在烘表阶段是 Python 侧的账，只有机内它才证明 <code>bossAnimInit</code> 那张 32 肢→槽的反查表真的建起来了；④ <strong>参考帧 0 的上屏与 S6 已验收的静态孪生 <code>57c47717_lkBoss_y0p-5_top.png</code>(2026-10-08 换锚, 旧名 <code>7996fa4a_…</code>) 逐字节相同</strong>，后面每一帧与帧 0 必须<strong>至少差 1 px</strong>（阈值 0，不是 manifest 给人读数用的 24）。第 ④ 条是这根链的锚：它把&quot;新通路画的静息姿势&quot;钉回已经验收过的那套几何与摆放，而不是只证明&quot;数量对得上&quot;。四台四帧 = gnd 待机 0/10、gnd 投掷 26、gndd 步行 15，读数 <code>Flex 逐帧接地门: ALL PASS (4 帧, ...)</code>，实物在 <code>evidence/anim_boss_device/</code>。<strong>这一门不判剪影形状</strong>（那是 S8f-4：<code>tools/anim_silhouette_gate.py</code> 的 boss 版，逐帧 IoU/一圈/下沿），也<strong>不判节奏</strong>。⚠ 这一栏早先记的理由是&quot;无头 desmume 里时钟不推进&quot;，<strong>那是把一行读数读错了，已推翻</strong>：两台不钉帧的探针 ROM 自印的 <code>BOSSA frame</code> 正好等于&quot;跑满 60 个屏帧&quot;应算出的那个值（<code>lkBt</code> <code>BOSSHZ=3</code> ⇒ 60/3=20 对 idle 段 20 帧取模 ⇒ 0；<code>lkBh</code> <code>BOSSHZ=2</code> ⇒ 30 mod 20 ⇒ <strong>10</strong>，且它自印的 <code>foot -6.1342/24</code> 与离线表<strong>帧 10</strong> 逐位相同 —— 那个帧号是机器自己数出来的，不是我喂给它的，所以这条比四台钉帧实物覆盖面更宽）。真正的事实是<strong>屏帧计数会饱和</strong>（<code>SETTLE</code> 从 2 s 加到 90 s 恒印 <code>frame 60</code>）而同期上屏还在动 ⇒ 读数与画面<strong>不成对</strong>：<code>lkBh</code> 的上屏与钉帧那台 <code>lkBg10</code> 差 <strong>137 px</strong>，而它自己印 <code>frame 10</code>。这句话同时给出两件事 —— &quot;节奏（真机 fps 下的观感）判不了&quot;的理由，以及&quot;实物必须把帧号钉在编译期&quot;的<strong>实测</strong>理由（钉死后读数与画面恒等，137 px 那种错位没有发生的余地）。探针的配方、md5 与逐条读数在 <code>evidence/anim_boss_device/manifest.txt</code> 的&quot;时钟探针&quot;一节；它们的图<strong>故意不归档</strong>（读数与画面不成对的图归档就是作伪证）。</p><h2 id="s8f-接地门负对照" tabindex="-1">S8f 接地门负对照 <a class="header-anchor" href="#s8f-接地门负对照" aria-label="Permalink to &quot;S8f 接地门负对照&quot;">​</a></h2><blockquote><p>实现:`tools/boss_frame_gate.py negctl --mode wrong-frame\\</p></blockquote><p>corrupt-limb<code>| &quot;命中&quot;这句话要有牙，两种错位式各实跑一遍且**四帧全红**：①</code>wrong-frame<code>—— 拿下一帧的离线预测去对同一张实机图 ⇒ 首条</code>-6.6133/24 != 机内 -6.6269/24<code>（帧 0 与帧 10 的最低点差 0.0136 单位，这条抓的是&quot;表读对了但没有对帧&quot;）。② </code>corrupt-limb<code>—— 把**整只接地脚**（凡拥有&quot;最低点上方 0.10 世界单位内顶点&quot;的那组 limb）整条改挂到槽表里的下一条 limb ⇒ 首条</code>-5.7796/24 != 机内 -6.6269/24<code>，Δ 0.85 单位。这两条的形状是试出来的，不是设计出来的：第一版负对照是把 </code>slotlimb<code> 表整体滚一格 —— 那是**双射**，预测逐字节不变，门绿得像什么都没发生（空对照）；改成&quot;只滚一个顶点的归属&quot;又太弱，另一只脚还撑着最低点，Δ 只有 0.0008/0.0027，**低于副屏的显示位宽** ⇒ 门会&quot;绿着错&quot;。与 S8 那条动画负对照同一条反直觉符号：</code>negctl` 退出码 <strong>rc=0 才表示&quot;每帧都红了&quot;</strong>，门里照这条判。</p><h2 id="s3-设备读数-离线读数" tabindex="-1">S3 设备读数 == 离线读数 <a class="header-anchor" href="#s3-设备读数-离线读数" aria-label="Permalink to &quot;S3 设备读数 == 离线读数&quot;">​</a></h2><blockquote><p>实现:<code>tools/ocr_console.py</code>（副屏截图 OCR）+ <code>gate_s3</code></p></blockquote><p>计划 S3 格那句「GPU 读数 == S1 JSON 读数（无丢包）」现在是门而不是散文。取数口只有副屏：ARM9 <code>printf</code> 到不了 desmume 宿主日志（宿主日志 = <code>tools/capture_screen.sh:33</code> 自己重定向的 <code>/tmp/desmume_$$.log</code>；复核配方：<code>bash tools/capture_screen.sh moribossroom_render.nds /tmp/x.png</code> 之后 <code>wc -c /tmp/desmume_*.log</code> 加 <code>grep -c &quot;entry floor|col |pos x|walk x\\[&quot;</code>。2026-10-06 现测两份，各 875 B、各 12 行，四类前缀<strong>全部 0 命中</strong>，其中一份按住 ↑ 跑 14 秒以排除&quot;每 30 帧才印一次&quot;的节拍混淆；盘上另存三份历史日志 873/874/875 B —— 字节数含 desmume 打印的时间戳与 PID，会漂 2 B，别把 875 当校验和，且历史那三份本次只核了字节数、没重跑 grep），而 ROM 每 30 帧把计数器重印上屏（<code>src_scene/main.c:441-455</code>）。三张存档截图（<code>83bd4dfa</code> / <code>82ddd8a6</code> / <code>b5e6a148</code>，三个不同机位；2026-10-08 换锚前它们叫 <code>dd9bfa50</code> / <code>5859b82f</code> / <code>64506eae</code>，读数字段一字未变）逐张读到 <code>GPU 1018/1018 OK</code>、<code>verts 1755 tex 22</code>、<code>BOSS 440/440</code>、<code>entry floor -193 want -193</code>。<strong>期望值全部现算</strong>：1018/1755/22 = <code>data/moribossroom_room_{0,1}.json</code> 的 <code>tris_total / verts_loaded / unique_textures</code> 求和，440 = <code>include/scene/boss_gnd.h</code> 的 <code>BOSS_NT</code>；因此这一行同时钉住两条链——ROM 头文件若与 S1 JSON 走岔（<code>R0_NT/R0_NV/BOSS_NT</code> 不齐）当场 FAIL，设备少交一个三角形也当场 FAIL。真实反证（改完即还原，S1 门复跑 32/32）：把 room_0 的三角形数与头文件一起少算 1 ⇒ <code>三角形 1018 != 离线 1017</code>；只改头文件 <code>R0_NV 694→700</code> ⇒ <code>R0_NV=700(离线 694)</code></p><h2 id="s4-环境参数四段一致" tabindex="-1">S4 环境参数四段一致 <a class="header-anchor" href="#s4-环境参数四段一致" aria-label="Permalink to &quot;S4 环境参数四段一致&quot;">​</a></h2><blockquote><p>实现:<code>gate_env</code>（<code>col_extract --emit-env</code> 现解 ROM + 读 <code>env_mori.h</code> + 读 <code>main.c</code> 字面量）</p></blockquote><p>计划 S4 那格的 <code>fogNear=940</code>/<code>zFar=1500</code>/<code>fovy=60°</code> 此前只在注释里为背书，而且<strong>ROM 侧根本不吃 <code>env_mori.h</code></strong>：<code>src_scene/main.c</code> 里是 <code>FOG_NEAR W2N(940)</code>、<code>FOG_FAR W2N(1500)</code>、<code>glFogColor(1,3,2,31)</code>、<code>glClearColor(ROOMS?1:…, ROOMS?3:0, ROOMS?2:…)</code> 四个手抄字面量。这一行把四段串起来：ROM 镜像现解 <code>fog=(10,23,14) fogNear 940 zFar 1500</code> == 头文件（<code>--emit-env</code> 重生成后<strong>逐字节相同</strong>）== <code>main.c</code> 字面量（fogNear/zFar 相等、RGB5 按 <code>round(v*31/255)</code> = <code>(1,3,2)</code> 与设备两处取色一致）== <strong>量具的 <code>--bg</code></strong>；另核 <code>fovy</code> 写法是 <code>60.0f*DEGREES_IN_CIRCLE/360</code>（硬件只吃 1/512 圈 ⇒ 85 ⇒ 59.766°）且透视分支远平面传的就是 <code>FOG_FAR</code>。<code>--bg</code> 那条不是装饰：协议 2 的整幅像素对比建立在&quot;背景色取对了&quot;上，此前只有散文背书。四条反证全部实测（都在 <code>/tmp</code> 副本上做，验收 ROM 的输入未被碰过）：<code>FOG_NEAR 940→941</code> ⇒ FAIL；<code>glFogColor(1,3,2)→(1,2,1)</code>（即用截断而非四舍五入换色）⇒ FAIL；量具 <code>--bg</code> 换成 <code>12,14,19</code> ⇒ FAIL；头文件 <code>ENV_ZFAR 1500→1200</code> ⇒ FAIL 并报&quot;与 ROM 现解的结果不一致&quot;。<strong>同一格还有一处命名层偏差</strong>（记在这里防止被当成偷改）：计划 S4 写的是 <code>gluPerspectivef32</code> + <code>gluLookAtf32</code>，实际只用了前者，视向改用矩阵栈 turntable（<code>T * Rx(pitch) * Ry(yaw) * T(-center)</code>），理由是正俯视 <code>pitch = ±90°</code> 时 <code>up=(0,1,0)</code> 与视线平行会退化，而顶视图正是本轮要的验收机位之一（出处与推导见 <code>src_scene/main.c:3-5</code>）；投影口径没变（<code>fovy</code> 仍走 <code>gluPerspectivef32</code>），与它同口径的 CPU 量具 <code>projPix</code> 被协议 2 那七行逐像素门钉住。另外计划的文件清单列了 <code>src_scene/camera.c</code>，实现里没有这个文件，相机与输入都在 <code>src_scene/main.c</code> —— 两处都是文件/命名层偏差，S4 的验收判据一条没少</p><h2 id="协议-2-光栅自洽-×7" tabindex="-1">协议 2 光栅自洽 ×7 <a class="header-anchor" href="#协议-2-光栅自洽-×7" aria-label="Permalink to &quot;协议 2 光栅自洽 ×7&quot;">​</a></h2><blockquote><p>实现:<code>tools/room_raster.py</code>（CPU 光栅 vs desmume 截图）</p></blockquote><p>七个机位（y0/y27/y60/y90/y180/y270埋墙/y270净空）几何 <strong>IoU_geom ≥0.996、&quot;只有真机画了&quot;≤124 px</strong>；色场六台 PASS（每通道≤1步 86.3~100.0%、≥9步 ≤1.17%），唯一 WARN 是眼点入墙的 y270（67.9%，<strong>玩家转视角就能触发</strong>：5975 个合法站立格里四个朝向各有 50~55% 让眼点落进极近几何档，根因是本轮不做的相机碰撞，见偏差 4）。同 yaw 的净空对照机位 100.0%/0 px ⇒ 残差归机位不归渲染。判据口径见 <code>tools/acceptance_gate.py:gate_raster</code>，读数见 <code>evidence/raster/manifest.txt</code>。<strong>与计划用词的对应</strong>（免得读计划的人以为这一行漏了东西）：计划协议 2 点名的 <code>tools/nds_raster.py</code> 是角色侧那只<strong>正交</strong> z-buffer（<code>glOrtho(-1.92,1.92,0.06,2.94)</code>，机位固定 ZOOM=1），而场景侧要的是透视，所以同一口径在本轮落地成 <code>tools/room_raster.py</code>（透视 + 投影前对视锥 6 个面做 Sutherland-Hodgman 裁剪；这条推翻过一版「跨近平面整片跳过」的量具策略，记录在 brain <code>scene-moribossroom-porting</code> 的 reversal 条目里）；计划那句&quot;IoU/bbox&quot;里的 IoU 在本行判，bbox 分两处判 —— 世界系 bbox 逐位对账在 S1 的 G11，屏幕剪影 bbox（<code>预测bbox x[..],y[..]</code> vs 实机）在 S6 本体剪影那一行（<code>cmp_boss</code>，同一族的深度归属行不报 bbox，它报的是遮挡/越界像素数）；<code>vision</code> 模型自始至终不参与评分，剪影与像素统计那几只量具（<code>tools/actor_silhouette.py</code>、<code>tools/boss_screen_predict.py</code>）与 <code>room_raster.fill</code> 同源（同一套边函数/重心坐标，&quot;Inside&quot;定义只有一份）</p><h2 id="协议-4-证据锚定" tabindex="-1">协议 4 证据锚定 <a class="header-anchor" href="#协议-4-证据锚定" aria-label="Permalink to &quot;协议 4 证据锚定&quot;">​</a></h2><blockquote><p>实现:<code>tools/evidence_audit.py</code></p></blockquote><p>0 个问题</p><h2 id="纪律-站点画廊可读性-协议-4" tabindex="-1">纪律 站点画廊可读性（协议 4） <a class="header-anchor" href="#纪律-站点画廊可读性-协议-4" aria-label="Permalink to &quot;纪律 站点画廊可读性（协议 4）&quot;">​</a></h2><blockquote><p>实现:<code>tools/gen_site.py --check-dist</code></p></blockquote><p><code>--check</code> 只管<strong>上游</strong>（清单列出的图在 <code>evidence/</code> 里真实存在），而人眼门（协议 3）判的是<strong>建好的站</strong>：从上游到 <code>dist</code> 中间还隔着一次 build，&quot;图糊得根本判不了&quot;这一类缺陷正好落在那一段没人看过的缝隙里 —— 本轮真撞见过两次（<code>&lt;td width=&quot;50&quot;&gt;</code> 在 HTML 里是 50 <strong>像素</strong>不是 50%，配上 <code>table-layout:fixed</code> 把两列各压成 50 px；七张拼图被塞进两列表格缩到 ~90 px）。这一行把判据放到 dist 上，六条：<code>gallery.html</code> 里的 <code>/shots/</code> 引用、<code>GALLERY</code> 清单、<code>dist/shots</code> 目录三方集合完全相等（不等就是&quot;页面引了空气&quot;或&quot;孤儿证据还躺在 dist 里当证据&quot;）、任何 PNG 为 0 字节即 FAIL、每个 <code>width=</code> 属性必须带百分号、<code>&lt;div class=&quot;sheet&quot;&gt;</code> 个数必须等于清单里拼图张数、dist 的 CSS 必须含 <code>.sheet</code> 规则（放开宽度那条样式没进去就等于没修），外加一条<strong>目的地口径</strong>：以引号/括号紧挨着的 <code>/nds-site/</code> 前缀，命中数按 <code>SITE_BASE</code> 决定该不该为 0 —— 设了就必须<strong>有</strong>（Pages 那份没前缀＝子路径整站 404），没设就必须<strong>没有</strong>（2026-10-09 之前这一条是单向的，于是门拿着旧目的地的口径量新目的地：把 Pages 的 dist 交上去它印 219 处命中并 FAIL，看着像污染，其实是判据过期；<code>acceptance_gate.py</code> 里那一格现在显式 <code>env={&#39;SITE_BASE&#39;: &#39;/nds-site/&#39;}</code>）。正文提这个字符串不算，见 §3 发布段。空判据按 FAIL：页面零引用 / 清单为空 / <code>dist</code> 不存在（没 build 就想体检）都直接判错而不是跳过。读数 <code>77 张三方一致 · 无 0 字节 · width 全带百分号 · 9 张拼图按 1:1 独占行且 CSS 有 .sheet · 前缀判据按 Pages 那份(/nds-site/ 前缀已核) 走</code>。<strong>功率是往真 dist 页面上注回历史缺陷测的</strong>（只在内存里换，盘上文件没动）：<code>width</code> 退成裸像素 ⇒ 抓到；一张拼图掉回两列表格 ⇒ <code>6 个 ≠ 7 张</code> 抓到；CSS 里删掉 <code>.sheet</code> ⇒ 抓到；<code>dist/shots</code> 少一张图 ⇒ 引用不齐抓到；图拷成 0 字节 ⇒ 抓到；往某个 <code>href</code> 里注一处 <code>/nds-site/</code> ⇒ 抓到（这条最早还反过来抓了我自己一次：判据第一版用裸串 <code>count()</code>，被本文档正文里提这个前缀的三处误报，判据据此收窄成只认 URL 位置）。13 条夹具在 <code>--selftest</code>（3 正例 + 10 反例：零引用 / 清单有而页面没引 / 孤儿证据 / 裸像素 width / 拼图掉回表格 / CSS 缺规则 / 0 字节 / 默认 base 那份串进 Pages 前缀 / Pages 那份没有前缀 / <strong>属性值里有裸双引号</strong>；三条正例是合规页、<code>&amp;quot;</code> 转义后的引号不许报警、Pages 那份带上前缀算合规；正例里留一处 <code>&lt;code&gt;/nds-site/&lt;/code&gt;</code> 正文提及，专门反证判据不瞎报）。<strong>那条引号判据是本轮真炸出来的</strong>：持剑那节的节标题带了 <code>&quot;丢失 0&quot;</code> 两个直双引号，被原样塞进 <code>alt=&quot;...&quot;</code>，<code>vitepress build</code> 报 <code>Attribute name cannot contain U+0022</code> 且<strong>炸在 <code>rm -rf dist</code> 之前</strong> —— 旧 <code>dist</code> 原地留着、时间戳与字节都没变，只看输出前几行会读成&quot;构建成功&quot;。生成侧同时改成 <code>html.escape(..., quote=True)</code>，两处（两列表格与拼图独占行）都得改：第一次只改了前者，反例是它自己报出来的。同一脚本的 <code>--check</code> 另加一条同源检查：从 <code>tools/acceptance_gate.py</code> 源码里用 <strong>AST</strong> 取 <code>ANCHORS</code> 与 <code>REBUILDS</code>（不 import —— 那脚本一跑就是几十次 <code>make</code>，这一行只是查表不是复现），要求每台被逐位复现钉住的 ROM 都在本表点得出名；名单读不出来即按空判据 FAIL。<strong>这条一上线就撞出一处手抄过期数</strong>：本表那行标题原写「逐位复现 ×29」，而名单当时实测是 33 台（两个验收锚点 + 31 台诊断孪生），<code>--rebuild</code> 实跑也正是 33 行逐位复现全 PASS —— 手抄计数没有机器出处就会这样悄悄过期。标题行已改写成从名单推出来的说法，<code>--check</code> 实跑读数「复现名单 51 台全部在 §4 点得出名(含验收锚点 2 台)」（S8f-3 那四台本体动画钉帧孪生进门之后，持剑那三台是 2026-10-08 又加的一档，<code>demoAnim</code> 是 2026-10-09 为录屏加的一台）</p><h2 id="纪律-声明读数对账-协议-4-不占一行" tabindex="-1">纪律 声明读数对账（协议 4，不占一行） <a class="header-anchor" href="#纪律-声明读数对账-协议-4-不占一行" aria-label="Permalink to &quot;纪律 声明读数对账（协议 4，不占一行）&quot;">​</a></h2><blockquote><p>实现:<code>acceptance_gate.py</code> 末尾那行 <code>OK/FAIL 声明读数对账</code></p></blockquote><p>上面那两条统计数（当时是 32 项 / 65 项，S8 之后是 36 项 / 75 项，S8d 攻击段四台进复现名单后是 36 项 / 79 项——多的四项全在逐位复现那一档，普通档一项没加；S8e 青年加农 Flex 骨架门与它的负对照各加一项，这次加在普通档（38 项），逐位复现那档跟着 +2 到 81 项；S8f-3 本体动画接地门与它的负对照又各加一项 ⇒ 普通档 40 项，四台钉帧孪生进名单 ⇒ 逐位复现那档 +4 到 87 项）此前是<strong>手抄</strong>的：加一行门忘了改本文、或改了本文忘了跑门，都静默漂着 —— 本轮就抓到过 <code>--rebuild</code> 63→64 与「逐位复现 ×29」→33 两次。现在每次跑完拿本次实测（总/PASS/WARN/FAIL）与本文那两行注释现读现比，regex 与 <code>tools/gen_site.py:gate_tally</code> 同一条，所以&quot;站里那两份数字&quot;和&quot;门自己的读数&quot;三方同源。这一格刻意<strong>不 <code>add()</code> 成一行</strong>：它一旦被算进总数，声明值就永远差 1，变成自指；它的判据落在<strong>退出码</strong>上（不符 ⇒ 整体 rc=1，与任何一行 FAIL 同级）。功率由 <code>cmp_tally</code>/<code>parse_tally</code> 那 8 例钉（见上一段）。紧挨着它的还有一条<strong>站点手抄对账</strong>（同一格退出码判，也不占一行）：<code>web/site/index.md</code>、<code>progress.md</code> 是人写的 —— <code>gen_site.py</code> 只再生 acceptance/pipeline/caveats/gallery 四页，单上游规则管不到这两页，而那几处的项数就是&quot;站里第二份抄本&quot;。<code>SITE_DECL</code> 把 5 处声明逐一抠出来（首页 2 处普通 + 2 处重编、进度页 1 处重编），按本次实测比：普通档只比标 <code>plain</code> 的那几处，并明说&quot;另有 3 处 <code>--rebuild</code> 项本次没跑，不比对&quot;；重编档两个实测值都算得出（普通项数 = 本次行数 − 逐位复现名单台数，现 51 台），这一减法是本轮真 FAIL 出来的口径修正，不是设计的优雅。5 处全读不出来 ⇒ 空判据 FAIL；格式变了抠不出数字 ⇒ FAIL。读法：<code>--rebuild</code> 那行只声明总数，所以重编档只比总数、分量不判；<code>--fast</code> 档按定义少跑 S0 一行，这一格印「跳过 ⇒ 不比对」而不是静默通过（实测：漂总数与漂 WARN 分量各跑一次全量档，两次 rc=1 并报出 <code>docs 31 != 实测 32</code> / <code>WARN docs 1 != 实测 2</code>，还原后 <code>OK 声明 == 实测</code>）</p><h2 id="纪律-夹具名单同源-协议-4" tabindex="-1">纪律 夹具名单同源（协议 4） <a class="header-anchor" href="#纪律-夹具名单同源-协议-4" aria-label="Permalink to &quot;纪律 夹具名单同源（协议 4）&quot;">​</a></h2><blockquote><p>实现:<code>tools/gen_site.py --check-fixture-roster</code></p></blockquote><p>§4 上面那一大段枚举把每家夹具的例数<strong>手抄</strong>成数字，而 <code>--selftest</code> 的名单是会长大的：新加一家忘了写进本文、或本文手抄数与实测漂移，都属&quot;文档声称有功率、机器没量过&quot;。这一行现跑 <code>python3 tools/acceptance_gate.py --selftest</code>（只喂合成夹具，不重编），取它自己吐出的名单，要求三件事同时成立：每一家在本文点得出名、本文写成「某家 N 例」的那个 N 等于实测、本文给出总数且等于实测之和；实跑任一家 FAIL 或退出码非 0 ⇒ 这一行 FAIL，名单读不出来也 FAIL（空判据一律 FAIL）。这条一上线就报了 9 处（漏名 6 家 + 压根没有总数那句），随后又抓到 <code>--rebuild</code> 总数 63 与「逐位复现 ×29」两个过期数。反证三条实测：总数 129 抄成 128 ⇒ FAIL；<code>cmp_budget</code> 的 12 改成 11 ⇒ FAIL；把一家名字从本文全部抹掉（<code>cmp_twin</code> 两处都改） ⇒ FAIL「夹具家族 cmp_twin 在 docs 里点不出名」。第三条的边界要说清楚：只抹一处<strong>不算</strong>漂移 —— 判据是&quot;点不点得出名&quot;，不是&quot;出现几次&quot;，所以它的功率在&quot;整家消失&quot;这一档。三次改动都在 <code>/tmp</code> 副本上做、每次还原后与实验前的上游副本逐位一致（当次 md5 <code>bab85527</code>，本文之后又长了一行，那个值自然不再是当前值）</p><h2 id="纪律-裁切守卫-协议-4" tabindex="-1">纪律 裁切守卫（协议 4） <a class="header-anchor" href="#纪律-裁切守卫-协议-4" aria-label="Permalink to &quot;纪律 裁切守卫（协议 4）&quot;">​</a></h2><blockquote><p>实现:<code>tools/zoom_crop.py --selftest</code></p></blockquote><p>协议 3 的 4x 放大素材由 <code>tools/zoom_crop.py</code> 裁出，它有三道守卫（裁框越出父图 / 空框或反向 / <code>scale&lt;1</code>）与一条&quot;必须是最近邻&quot;的实现约束。这一行不判画面，判<strong>量具本身会不会静默降级</strong>：夹具 10 例 = 2 条正例（2×2 图案整幅 2x 放大后每个原像素必须被复制成 2×2 块；单像素裁框必须是纯色）+ 1 条&quot;换成 BILINEAR 就必须 FAIL&quot;的反证 + 7 条守卫反例（x1 越界 / y1 越界 / 负坐标 / 空框 / 反向框 / scale=0 / scale 负）。守卫被拆掉时 PIL 会裸抛 <code>ValueError</code>，夹具把它记成 <code>GUARD-MISSING</code> 并判 FAIL —— 漏判不许伪装成崩溃以外的&quot;没测到&quot;。功率实测：把 <code>Image.NEAREST</code> 就地换成 <code>BILINEAR</code> ⇒ 该族 FAIL；把 <code>if scale &lt; 1</code> 改成 <code>if False</code> ⇒ 该族 FAIL（两次都在 /tmp 副本上做，盘上工具未动）</p><h2 id="纪律-提取器段掩码-协议-4" tabindex="-1">纪律 提取器段掩码（协议 4） <a class="header-anchor" href="#纪律-提取器段掩码-协议-4" aria-label="Permalink to &quot;纪律 提取器段掩码（协议 4）&quot;">​</a></h2><blockquote><p>实现:<code>tools/room_extract.py --selftest</code></p></blockquote><p>计划点名的那处修复（<code>scripts/f3dex2_extract.py</code> 的 <code>&amp; 0x1FFFFFF</code> → <code>&amp; 0xFFFFFF</code>）<strong>此前只有间接覆盖</strong>：S1 每次跑都重解房间 DL、S6 每次跑都重解本体 limb，掩码退化会在「694/408」「699/440」这类总量守恒上响，但报的是「数字不对」，不是「哪一行语义错了」。这一族直接判段地址语义本身（gbi.h：段号占高字节、低 24 位才是镜像内偏移），不读 ROM，8 例 = 段 3 按低 24 位解 / 段 6 那档不许跟着变 / <code>seg_key</code> 保住段号 / 段 2（父场景）与段 3 同偏移必须可区分 / 地址 0 与地址字段缺失都解成 <code>None</code> 而不是偏移 0 / 旧掩码对奇段 3 必须与权威解<strong>不等</strong> / 旧掩码对偶段 6 侥幸<strong>相等</strong>（这条把「bug 为什么历史上一直不响」也钉住）。功率实测两次且<strong>分得清是哪个点位坏的</strong>：在派生的临时副本里只回退 <code>seg_off</code> ⇒ 漏判 2（第 1、7 例）、只回退 <code>seg_key</code> ⇒ 漏判 1（第 3 例），原版同场对照漏判 0；副本用后即删，盘上工具与已验收 JSON 未动。⚠ 它<strong>不是</strong>夹具名单的第 16 家 —— <code>--check-fixture-roster</code> 只收 <code>acceptance_gate.py --selftest</code> 自己吐出的名单，工具侧家族（<code>zoom_crop</code> 10 例、这一族 8 例）各归各的门行，与 <code>cmp_*</code> 那 17 家 172 例分开计</p><h2 id="纪律-flex-槽表负对照-协议-4" tabindex="-1">纪律 Flex 槽表负对照（协议 4） <a class="header-anchor" href="#纪律-flex-槽表负对照-协议-4" aria-label="Permalink to &quot;纪律 Flex 槽表负对照（协议 4）&quot;">​</a></h2><blockquote><p>实现:<code>tools/boss_extract.py --selftest</code></p></blockquote><p>S8e 那条「收尾矩阵 == 自身」的牙不能只靠一次 /tmp 手工实验背书，所以四类错法加一条回归固定在门里跑（每例现解一遍 ROM，实测 0.4 s/次）。6 例 =「正例：槽表未打补丁 ⇒ 14 行全绿」（没有正例对照，「只有第三条红」这句话不成立）+ 三种<strong>槽表错位</strong>（键整体 +1、整表反转、逐槽右移一位）各自期望的红集合<strong>恰好</strong>是「收尾矩阵」这一条——前两条 Flex 判据对它们全不敏感（槽号照样全解得出、<code>走查零 issue</code> 一条不报）；其中「逐槽右移一位」是三种里最狠的一式：槽数不变、每条 G_MTX 都解得出、关节顶点全部挂到邻骨名下，只有收尾那一条会响 + 一种<strong>槽表缺失</strong>（空表）期望红集合恰好是「G_MTX 全部解到合法槽 / 槽表数量 == 有网格 limb 数 / 走查零 issue」三条——这一例把「槽表没建」与「槽表建错」分开报，不许混成同一声红 +「回归：<code>object_gnd</code> 必须走 Standard 分支且 12 行全绿」。判的是<strong>红行集合相等</strong>而不是「有行红」，所以判据本身退化（有人把第三条改成永真、或把空表那种错也当合法槽放过）会当场在这族里响。⚠ 它<strong>不是</strong>夹具名单的第 17 家，理由与上面 <code>room_extract</code> 那行相同（<code>--check-fixture-roster</code> 只收 <code>acceptance_gate.py --selftest</code> 自己吐出的名单）</p><h2 id="纪律-录屏素材自洽-协议-4" tabindex="-1">纪律 录屏素材自洽（协议 4） <a class="header-anchor" href="#纪律-录屏素材自洽-协议-4" aria-label="Permalink to &quot;纪律 录屏素材自洽（协议 4）&quot;">​</a></h2><blockquote><p>实现:<code>tools/video_frames.py --audit</code></p></blockquote><p>站点上那句「相邻帧间变化 …、没有一对静止」此前是<strong>一次性手测</strong>，盘上没有重算的路子。现在它有两个实物：<code>evidence/video/frames/</code>（99 张 256×192 帧）与 <code>evidence/video/manifest.txt</code>，门现跑现比 —— 逐张帧 md5-8、相邻差异<strong>从像素重算</strong>（本次 min=398 / max=48372 / 静止对 0）、<code>frames</code>/<code>diff_min</code>/<code>diff_max</code>/<code>static_pairs</code> 四个声明数必须等于重算值、清单与盘上帧集合必须互为相等（多一张孤儿帧也算不齐）、<strong>快门账要平</strong>（声明拍 100 次 − 丢 1 张 = 交付 99 帧，丢的那张必须登记帧名）、录屏 ROM 的 md5-8 必须在锚点或逐位复现名单里（本次 <code>550345a4</code>）、交付 mp4 的 md5-8 与字节数必须对得上实物（本次 <code>0a42c721</code> / 1152305 B）。判据与夹具同一只文件（<code>cmp_video</code> 17 例，含一条 <code>emit</code>→<code>audit</code> 往返自洽 —— 这条是踩出来的：<code>emit</code> 曾把帧名写成裸序号，自己写的清单自己读不回，「没有帧行」永远 FAIL）。为什么丢那一帧：无头 desmume 偶尔连着两次快门落在<strong>同一个屏帧</strong>里（实测 100 次快门 1 次，<code>f065</code>/<code>f066</code> 逐像素全等），重复帧不带新信息，留在片子里就是拿静止对稀释「确实在动」这句话；原始快门留在拍摄目录、映射写进 <code>frames/dedup.map</code>，所以「丢了哪张、它原本是谁」本身可查</p><h2 id="锚定-rom-×2-rebuild-连锚点共复现-51-台-其中诊断孪生-49-台" tabindex="-1">锚定 ROM ×2（<code>--rebuild</code> 连锚点共复现 51 台，其中诊断孪生 49 台） <a class="header-anchor" href="#锚定-rom-×2-rebuild-连锚点共复现-51-台-其中诊断孪生-49-台" aria-label="Permalink to &quot;锚定 ROM ×2（`--rebuild` 连锚点共复现 51 台，其中诊断孪生 49 台）&quot;">​</a></h2><blockquote><p>实现:md5</p></blockquote><p><code>link_full_render.nds</code> = <code>8a546db4</code>、<code>moribossroom_render.nds</code> = <code>83bd4dfa</code>，<code>rm -rf build/&lt;NAME&gt;</code> 重编不变。锚的链条：<code>66fb25a5</code>（纹理修复前）→ <code>dd9bfa50</code>（2026-10-04，<code>LINKTEX</code> 旋钮落地但默认 0）→ <strong><code>83bd4dfa</code>（2026-10-08，只把 <code>LINKTEX</code> 的默认值从 0 翻成 1，源码里没有第二处改动）</strong>；旧锚那两份 .nds 已不在盘上，被新锚覆盖同名文件。2026-10-05 另做过<strong>整树清空</strong>复核（把 <code>build/</code> 整个移开，只跑 <code>make -s</code> 与 <code>make -s SCENE=moribossroom WALK=1 BOSS=1 STARTX=15 STARTZ=-2900 CAMYAW=0.0 CAMPITCH=-5.0</code>）两台锚点仍分别是当时的 <code>8a546db4</code> / <code>dd9bfa50</code> ⇒ 锚点不依赖任何留在 <code>build/</code> 里的旧产物；2026-10-08 换锚后又把同一试验重跑了一遍（同样把 <code>build/</code> 整个移开、只跑那两条命令），两台仍是 <code>8a546db4</code> / <code>83bd4dfa</code>；2026-10-05 另做了<strong>从锚点 ROM 到像素的现跑复核</strong>（和&quot;重编再比 md5&quot;相反的方向）：把磁盘上那份 <code>dd9bfa50</code> 重新在无头 desmume 里起一遍、按同一裁剪配方截上屏，与归档证据图 <code>evidence/eye/dd9bfa50_pitch-5.png</code>（换锚后这张叫 <code>83bd4dfa_pitch-5.png</code>）逐像素比是 <strong>0/49152 全等</strong>；副屏差 50/49152，而这 50 个像素全部落在行 104~110、列 216~230 那一带 —— 是每 30 帧重印一次的 <code>frame</code> 计数器（归档那张印 <code>frame 0</code>，现跑这张印 <code>frame 30</code>），其余逐字节相同。这一句把&quot;证据图出自这份字节&quot;的依据从「配方能重编出同样的字节」加严成「<strong>这份字节今天还能画出同样的像素</strong>」；<code>--rebuild</code> 复现 <code>lkWalk303060</code>/<code>lkWp600300</code>/<code>lkWyr600300</code> 那三台 0/49152 走的是同一条道理（见下面那句&quot;键驱动那张图&quot;）；<code>--rebuild</code> 另复现 yaw=270 净空诊断孪生 <code>lkG270f.nds</code> = <code>0ccb8e9c</code>（协议2 那一行靠它）与四台剔除证据实物 <code>lkC27 3142a54e</code> / <code>lkN27 491e1ca3</code> / <code>lkC300 4c8b461e</code> / <code>lkCE270 8d011205</code>（覆盖&quot;剔到 10/16&quot;、&quot;剔到 5/16&quot;、&quot;双房间&quot;、&quot;贴墙分叉&quot;四种读法各留一台实物），再加本体剪影门那两台 <code>lkBoss 57c47717</code> / <code>lkB90 b3a793a6</code>（<code>ROOMS=0 LINKDRAW=0</code> 是那条判据成立的前提，所以这两个旋钮也得被逐位复现钉住），以及本体深度归属门那五台 <code>lkOcclN 8f771f24</code> / <code>lkOcclL 3a984de9</code> / <code>lkOc2 4ef4540f</code> / <code>lkOc2N b69f57e9</code> / <code>lkOc2L 90790b13</code>（同机位的 full/noboss/linkonly 三件套 + 近机位三件套）、以及三台行走人眼素材的孪生 <code>lkWalk303060 87808691</code> / <code>lkWp600300 481e34b5</code> / <code>lkWyr600300 462551c2</code> —— 键驱动那张图的站位与机位<strong>不是命令里的常量</strong>（按住 ↑ 的墙钟时长随负载变、A 键每帧 +2°），唯一把它钉住的东西就是那台同值编译期孪生的 0/49152；因此改了行走或相机链路就会让这几台字节变化、门当场响，那几张键驱动图也当场失去&quot;验收 ROM 画的&quot;这个身份。xlu 层门那<strong>同批七台</strong>也在名单里：<code>lkQ39F 3060a599</code> / <code>lkQ39O a6547d43</code> / <code>lkQ39X a937f03f</code> / <code>lkQ39A 45785b18</code> / <code>lkQ39N 958ba4a5</code> 加两台 <code>FOG=0</code> 的 <code>lkQ39RF 2a2079eb</code> / <code>lkQ39RO 419d8273</code>（p39 判据机位，只差被检那一位）；对照机位 p25 那五台 <code>lkX2F 8d749d84</code> / <code>lkX2O a69e9557</code> / <code>lkX2X 0a8008f6</code> / <code>lkX2XA 27ecf88f</code> / <code>lkX2N 2b390c26</code> 也逐位复现 —— 它们不作判据，但&quot;推翻 A&quot;那句要靠这五张帧重讲，所以字节也得钉住。<strong>&quot;同批&quot;是 xlu 那条门的前提</strong>（见 <code>evidence/xlu/manifest.txt</code> 推翻 B），把它钉进 <code>--rebuild</code> 就是让&quot;混批次做差分&quot;这条路走不通。深度门远机位的 full <strong>不另立条目</strong>：它的字节与锚点 <code>83bd4dfa</code> 完全相同（<code>NAME=</code> 不改一个字节），所以那份名单同时钉住了&quot;这一行量的成品帧就是交付 ROM&quot;这句话。S8 逐帧动画门那<strong>十台</strong>也在名单里：<code>agBlank 1d544cdd</code> / <code>agW0 39fa8089</code> / <code>agW10 23728efd</code> / <code>agW20 3cbe6ae5</code> / <code>agI0 9fea8af5</code> / <code>agI14 4f27fae8</code> / <code>agA1 07d10f6c</code> / <code>agA4 c15433fc</code> / <code>agA8 31aec498</code> / <code>agA13 482adb11</code>（十台只差 <code>ANIMSEL</code>/<code>ANIMFRAME</code> 两位，<code>ROOM=0 BOSS=0 LINKBBOX=1 CAMDIST=90.0</code> 整套相同；<code>agBlank</code> 另加 <code>LINKDRAW=0</code> 当纯色底；<code>ANIMSEL=2</code> 那四台是 S8d 的攻击段）。<strong>前六台的 md5 是 S8d 重锚过的值</strong>：S8d 把攻击段接进 <code>#if LINKANIM</code> 分支后 <code>--rebuild</code> 当场报那六台逐位复现 FAIL（锚点两台一字不变 ⇒ 改动确实被旋钮挡在交付 ROM 之外），于是六台连编两遍取新字节、六张图重拍；<code>lkbbox</code>/<code>lksum</code> 与旧图逐位相同、只有 <code>pos z</code> 随宿主负载漂了几个单位，所以这次重锚换的是&quot;这台机器是谁&quot;而不是&quot;这一帧画了什么&quot;（详见 <code>evidence/anim/manifest.txt</code>）。这一门进十台的理由与别的孪生不同：它的第 0 条判据是<strong>设备上那份 limb 矩阵表与离线读的那份逐位相等</strong>（副屏 <code>lksum</code>），而这句话成立的前提是&quot;截图出自这十台字节之一&quot;——ROM 字节一变，九张图上的「校验和 一致」就退化成&quot;对着一台不认识的机器空判&quot;，所以<strong>门读的图与名单里的字节必须一一配对</strong>，<code>LINKBBOX=1</code> 也必须在（它带出 <code>lkbbox</code>/<code>lksum</code> 两行读数，没有它校验和没有来源）。帧号写进编译期旋钮而不是按键驱动，正因为这条门要的是&quot;这一帧&quot;而非&quot;某一次按键的结果&quot;。<strong>S8f-3 本体动画那四台</strong>走的是同一条道理、也在名单里：<code>lkBg0 d875350a</code> / <code>lkBg10 13a1fccf</code> / <code>lkBa26 4c7bd19c</code>（gnd 幻影加农 待机帧 0/10、投掷帧 26）/ <code>lkBd15 88f8af97</code>（gndd 青年加农 步行帧 15）。四台只差 <code>BOSSFORM</code>/<code>BOSSSEG</code>/<code>BOSSFRAME</code> 三位，<code>WALK=1 BOSS=1 BOSSANIM=1 LINKDRAW=0 ROOMS=0</code> 与那套机位旋钮整套相同（配方出处 <code>evidence/anim_boss_device/manifest.txt</code>）。这台门读的数是<strong>副屏自印的 <code>BOSSA ... foot</code></strong>（<code>tools/ocr_console.py</code> 抠字），判据是&quot;机内那次逐顶点整数变换的全身最低点 == 离线从 <code>include/scene/boss_anim.h</code> 现算的 <code>YMIN + anchor/65536</code>&quot;，所以它同样要求&quot;截图出自这四台字节之一&quot;——字节一变，四张图上的&quot;命中&quot;就退化成对一台不认识的机器空判。<code>ROOMS=0 LINKDRAW=0</code> 在这里还不只是构图：帧 0 与已验收静态孪生 <code>lkBoss 57c47717</code> <strong>逐字节相同</strong>这条锚，只有在画面只剩本体时才成立。<strong>持剑变体那三台</strong>也在名单里：<code>lkSwLa d1382338</code> / <code>lkSwLb 58a31a5c</code> / <code>lkSwLa0 7bc951eb</code>（两台持剑各一个机位 + yaw90 那台的无剑对照；y0 的无剑对照就是在册的 <code>lkLa33a 4c2f2908</code>，<code>NAME=</code> 不改一个字节，故不另立条目）。它们进名单的理由与交付锚点不同：<code>LINKSWORD</code> 默认 0 ⇒ 这三台<strong>不是</strong>交付实物，但「剑在手里」那条判据读的是<strong>差集两端的像素</strong>，不钉字节的话站点上那四张图就退化成「对两台不认识的机器空判」。2026-10-08 先证再锚：每台 <code>rm -rf build/&lt;NAME&gt;</code> 连编两遍、两遍逐字节相同。<strong>录屏演示那台</strong>也在名单里：<code>demoAnim.nds</code> = <code>550345a4</code>（配方整套抄 <code>evidence/video/manifest.txt</code> 的 <code>recipe</code> 行：<code>SCENE=moribossroom</code> 加 <code>WALK=1 BOSS=1 STARTX=15 STARTZ=-2900 CAMYAW=0.0 CAMPITCH=-5.0 DEMO=1 LINKANIM=1 BOSSANIM=1 LINKTEX=1</code>）。它进名单的理由与持剑三台同源但更硬：<code>tools/video_frames.py</code> 有一条判据是「录屏 ROM 的 md5-8 必须在锚点或逐位复现名单里」，读的就是这张表 —— 名单里没有它，站点上那句「录屏出自验收名单里的字节」当场 FAIL；而它若在名单里却字节漂了，那 99 张帧就退化成「对一台不认识的机器放电影」。2026-10-09 先证再锚：<code>rm -rf build/demoAnim</code> 连编两遍、两遍逐字节相同（<code>550345a4</code>）；同一次改动（<code>s_demo[]</code> 加了挥剑与本体出招两段剧本）之后两台交付锚点仍分别复现 <code>8a546db4</code> / <code>83bd4dfa</code> ⇒ 剧本没漏进交付 ROM。⚠ 复现时旋钮必须整套照抄 <code>evidence/cull/manifest.txt</code>、<code>evidence/boss/manifest.txt</code>、<code>evidence/xlu/manifest.txt</code>、<code>evidence/anim/manifest.txt</code>、<code>evidence/anim_boss_device/manifest.txt</code>、<code>evidence/sword/manifest.txt</code>：<strong>显式传&quot;与默认值相同&quot;的位姿参数会得到不同的 .rodata</strong>（实测同像素的两份 ROM 差 1024 字节），漏抄就必然 md5 不符。更要紧的是<strong>后果不是&quot;测不出来&quot;而是&quot;改掉验收实物&quot;</strong>：<code>make</code> 的产物直接落在仓库根的 <code>$(NAME).nds</code> 上，一台不带旋钮的 <code>make SCENE=moribossroom</code> 会把盘上那份 <code>83bd4dfa</code> <strong>原地覆盖</strong>成默认构建的 <code>c8fee40d</code>（2026-10-08 现测，<code>NAME=lkBare</code>；旧锚那一轮撞见过的是 <code>9ac35a04</code>，那个号也随默认值翻而动过），快门那条&quot;锚定 ROM&quot;当场 FAIL）。复现要整套照抄上面那条配方，且 <code>build/&lt;NAME&gt;</code> 必须先 <code>rm -rf</code> —— 2026-10-08 复测：同一个 <code>build/</code> 目录不清、先跑无旋钮构建再跑全套旋钮，输出的<strong>仍是</strong> <code>c8fee40d</code>；把 <code>build/lkBare</code> 清掉再跑同一套全套旋钮才复现出 <code>83bd4dfa</code>（而 <code>NAME=lkBare</code> 与 <code>NAME=</code> 缺省的 <code>moribossroom_render</code> 两份字节逐位相同 ⇒ 再一次证明 <code>NAME=</code> 不改一个字节）</p><h2 id="协议-3-人眼" tabindex="-1">协议 3 人眼 <a class="header-anchor" href="#协议-3-人眼" aria-label="Permalink to &quot;协议 3 人眼&quot;">​</a></h2><blockquote><p>实现:无（<code>acceptance_gate</code> 末尾只列素材清单）</p></blockquote><p><strong>只能由人判</strong>。当前素材 8 张拼图，每张在 <code>evidence/eye/manifest.txt</code> 里写明&quot;哪份 ROM（md5-8）/ 什么机位 / 判什么&quot;。<strong>先看 <code>_2026-10-05_final.png</code>（协议 3 终检图）</strong>：本轮范围内的&quot;场景 + 本体 + Link 可行走&quot;各给一格，一票判完，不必再翻前面几张。四格全部出自验收名单里的字节（第 1/3/4 格就是锚点 <code>83bd4dfa</code> 本身，第 2 格是 <code>--rebuild</code> 覆盖的 <code>lkOc2 4ef4540f</code>），每格只问一件事 —— ① 竞技场全景对不对（room_1 全 11 组入画 + 本体在位。<strong>入口房不在这一格</strong>：它在相机背后 —— 眼点 (15,27,−2810)（= <code>pos</code> 身后 <code>CAM_DIST=90</code>、上方 <code>CAM_H=60</code>，<code>src_scene/main.c:69,72,346</code>）、yaw 0 / pitch −5，<code>tools/room_cull_predict.py</code> 实印 room_1 前景 49143 px（<code>cg 0 7ff</code>，610 面）、room_0 0/5 组 0 px；副屏那栏 <code>GPU 1018/1018</code> 是「两间全量提交、未剔除」，不是「两间都看得见」，要看入口房另有 <code>uvfix/fffc9ee4_ortho_room0_top.png</code>）；② 本体被 Link 挡在前面像不像（离线说这机位必须有 166 px 被吃掉）；③ 走到位之后比例与四肢（Link 全身 73 px 入屏、脚 179/头 106，本体 51 px、脚 100/头 50）；④ 转的是相机、不是把场景重画一遍（人剪影不动、本体滑到 x87、墙面与窗一起转）。它<strong>不含</strong> xlu 那块共面亮板的人眼诉求：交付帧里可见的是 689 px 一条窄带，而&quot;谁盖住谁&quot;落在深度量子以下 —— 人眼判得了&quot;有没有一块亮板&quot;，判不了平局。其余 7 张是分项：<code>contact_sheet_2026-10-04_texfix.png</code> 纹理修复后有没有纹理；<code>_persp.png</code> 透视下墙上的画是不是真纹理、比例对不对；<code>_camclear.png</code> 协议 2 唯一那条 WARN（埋墙机位 vs 净空机位同一场景）；<code>_2026-10-05_bossdepth.png</code> 深度归属门里&quot;那批像素确实是本体、166 px 那条带确实是 Link 挡在前面&quot;（只管本体 vs Link 那一侧）；<code>_2026-10-05_walk.png</code> 按 ↑ 走到 z−3015 之后全身入屏 —— 人与本体的比例、四肢装配、走的是不是同一个房间；<code>_2026-10-05_turn.png</code> 同一条 ROM 再转 18° —— 判&quot;转的是相机、不是把房间重画成另一个场景&quot;（纹理修复后的 ROM 上，替掉 stale/ 里那张 yaw27）。<code>_2026-10-06_zoom.png</code> 是<strong>放大素材</strong>：终检每格只把 256×192 放大 2 倍，判得了整场景、判不了关节缝与袖子朝向（那些特征原生只有 8~20 px），所以按副屏自证读数（Link 脚 179/头 106、本体脚 100/头 50）与 <code>evidence/boss/manifest.txt</code> 的实测 bbox 钉出三个统一 76×136 裁框，整数倍最近邻放大 4×（不平滑 —— 平滑会造出原图上没有的像素值）。它不新增判据，只把已有证据摆到看得清的尺寸。拼图是审阅辅助、不是证据：权威始终是 manifest 里逐张锚定的单张 PNG，而&quot;每张图都能用当前源码逐位复现&quot;由 <code>--rebuild</code> 与 <code>tools/evidence_audit.py</code> 共同守着。⚠ <code>_persp.png</code> 前三格背后的三台变体 ROM（<code>lkTexW 85ce1db0</code> / <code>lkTexFar 507db893</code> / <code>lkBxFar</code>）<strong>不在</strong> <code>--rebuild</code> 那 51 台名单里。2026-10-06 曾按 <code>evidence/uvfix/manifest.txt</code> 的旋钮整套照抄、逐台 <code>rm -rf build/&lt;NAME&gt;</code> 重编，三台<strong>全部逐位相同</strong>；2026-10-08 换锚时又照同一旋钮重编：<code>lkTexW</code>/<code>lkTexFar</code> 各换出 <code>85ce1db0</code>/<code>507db893</code>，而两张上屏图与旧归档<strong>逐位相同</strong>（那两格里没有 Link 的身体）；<code>lkBxFar</code> 那台<strong>今天编不出记录里的那个号</strong> —— 两份清单给它的旋钮彼此矛盾（<code>evidence/eye/manifest.txt</code> 记 <code>LINKDRAW=0</code>、<code>evidence/uvfix/manifest.txt</code> 记 <code>LINKDRAW=1 + LINKBBOX=1 + CAMDIST=300.0</code>，两套却都写同一个 <code>d8e6f4d3</code>），2026-10-08 把两套各编一遍得到 <code>38198476</code> 与 <code>58b24637</code>，两个都不是 <code>d8e6f4d3</code> ⇒ 第 3 格是换锚前的实物：判 Link 的纹理与比例看第 4 格，别拿第 3 格当画质证据（逐条实测记在 <code>evidence/uvfix/manifest.txt</code> 顶部）。这是一次性实测而非门守；把这三台加进名单属于扩门，留给用户点头</p>',115)])])}const q=e(s,[["render",r]]);export{p as __pageData,q as default};
